  min-width:var(--wx-avatar) !important;
  border:0 !important; border-radius:var(--wx-avatar-r) !important;
  box-shadow:none !important; overflow:hidden !important;
  object-fit:cover !important; background-size:cover !important; background-position:center !important;
}
:is(.msg-avatar-them-inner, .msg-avatar-me-inner) img{
  width:100% !important; height:100% !important;
  border-radius:var(--wx-avatar-r) !important; object-fit:cover !important;
}

/* ==========================================================
   3. 气泡  方角 4px · 靠头像那侧三角尾巴 · 16/22 字号
   ========================================================== */
.msg-bubble-wrapper{ position:relative !important; }
.bubble-me-custom, .bubble-them-custom,
.bubble-deco-me, .bubble-deco-them,
.msg-bubble-container, .msg-content-stack{ overflow:visible !important; }
.msg-content-stack{ position:relative !important; }

.bubble-them-custom,
.bubble-me-custom{
  position:relative !important; box-sizing:border-box !important;
  max-width:68vw !important;
  padding:7px 12px !important;
  border:0 !important; border-radius:var(--wx-radius) !important;
  box-shadow:none !important; text-shadow:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  font-size:16px !important; line-height:22px !important;
}
.bubble-me-custom{ background:var(--wx-me) !important; background-image:none !important; color:var(--wx-me-ink) !important; }
.bubble-them-custom{ background:var(--wx-ta) !important; background-image:none !important; color:var(--wx-ink) !important; }
.bubble-me-custom :is(span,p,div,a,strong,em):not(.msg-translation-btn):not(.msg-translation-btn *){ color:var(--wx-me-ink) !important; }
.bubble-them-custom :is(span,p,div,a,strong,em):not(.msg-translation-btn):not(.msg-translation-btn *){ color:var(--wx-ink) !important; }

.bubble-them-custom :is(p,span,div):not(.msg-translation-wrapper):not(.msg-translation-btn):not(.msg-translation-btn *),
.bubble-me-custom :is(p,span,div):not(.msg-translation-wrapper):not(.msg-translation-btn):not(.msg-translation-btn *){
  max-width:none !important;
}
.bubble-them-custom, .bubble-me-custom,
.bubble-them-custom :is(p,span,div), .bubble-me-custom :is(p,span,div){
  word-break:normal !important; overflow-wrap:anywhere !important;
  line-break:auto !important; text-wrap:wrap !important;
}

.bubble-me-custom::before,
.bubble-them-custom::before{ content:none !important; }
.bubble-me-custom::after,
.bubble-them-custom::after{
  content:"" !important; position:absolute !important;
  top:var(--wx-tail-top) !important; bottom:auto !important;
  width:0 !important; height:0 !important;
  border-top:6px solid transparent !important; border-bottom:6px solid transparent !important;
  background:none !important; pointer-events:none !important; z-index:1 !important;
}
.bubble-me-custom::after{
  right:-6px !important; left:auto !important;
  border-left:6px solid var(--wx-me) !important; border-right:0 !important;
}
.bubble-them-custom::after{
  left:-6px !important; right:auto !important;
  border-right:6px solid var(--wx-ta) !important; border-left:0 !important;
}
:is(.bubble-them-custom,.bubble-me-custom):has(img, video, [class*="card"]){
  background:transparent !important; padding:0 !important;
}
:is(.bubble-them-custom,.bubble-me-custom):has(img, video, [class*="card"])::after{ display:none !important; }

/* ==========================================================
   4. 时间戳 / 日期 / 撤回  居中方角小框
   ========================================================== */
:is(.timestamp-custom, .date-divider-custom, .msg-recalled .msg-system){
  display:table !important; box-sizing:border-box !important;
  width:auto !important; max-width:80vw !important;
  margin:8px auto !important; padding:5px 10px !important;
  background:var(--wx-chip) !important;
  border:.5px solid var(--wx-chip-line) !important; border-radius:var(--wx-radius) !important;
  -webkit-backdrop-filter:blur(6px) !important; backdrop-filter:blur(6px) !important;
  color:var(--wx-chip-ink) !important; opacity:1 !important;
  font-size:13px !important; line-height:16px !important; font-weight:700 !important;
  letter-spacing:.02em !important; text-align:center !important; white-space:nowrap !important;
}
.msg-recalled .msg-system *{ color:var(--wx-chip-ink) !important; }
.msg-status-custom{ color:var(--wx-gray) !important; }

/* ==========================================================
   5. 引用  正文气泡在上 · 浅灰方角引用框在下 · 严格两行
   ========================================================== */
.msg-reply-block{ display:none !important; }
.msg-reply-block-detached{
  display:-webkit-box !important; -webkit-box-orient:vertical !important; -webkit-line-clamp:2 !important;
  position:relative !important; box-sizing:content-box !important;
  width:max-content !important; min-width:0 !important; max-width:calc(60vw - 18px) !important;
  height:auto !important; max-height:36px !important;
  margin:6px 0 0 0 !important; padding:0 9px !important;
  background:var(--wx-quote) !important;
  border:0 !important; border-left:0 !important;
  border-top:6px solid var(--wx-quote) !important; border-bottom:6px solid var(--wx-quote) !important;
  border-radius:var(--wx-radius) !important;
  box-shadow:0 0 0 .5px var(--wx-quote-line) !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  transform:none !important; clip-path:none !important; opacity:1 !important;
  font-size:13px !important; line-height:18px !important; color:var(--wx-gray-dk) !important;
  white-space:normal !important; word-break:break-word !important; overflow:hidden !important;
}
.msg-reply-detached-me{ align-self:flex-end !important; }
.msg-reply-detached-them{ align-self:flex-start !important; }
.msg-reply-block-detached::before,
.msg-reply-block-detached::after{ content:none !important; }
.msg-reply-block-detached *{
  display:inline !important; margin:0 !important; padding:0 !important;
  font-size:13px !important; line-height:18px !important;
  font-style:normal !important; font-weight:400 !important;
  opacity:1 !important; text-transform:none !important;
  white-space:normal !important; max-width:none !important; overflow:visible !important;
  color:var(--wx-gray-dk) !important; background:transparent !important;
}

/* ==========================================================
   6. 翻译  点气泡展开/收起 · 气泡下方 4px · 方角卡 · 灰圈白勾 + 说明
   ========================================================== */
.msg-translation-wrapper{
  position:static !important; height:0 !important; min-height:0 !important;
  margin:0 !important; padding:0 !important; line-height:0 !important;
  background:transparent !important; border:0 !important; overflow:visible !important;
}
.msg-translation-wrapper .msg-translation-content{ display:none !important; }

.msg-translation-btn{
  position:absolute !important; inset:0 !important;
  top:0 !important; left:0 !important; right:0 !important; bottom:0 !important;
  width:100% !important; height:100% !important; transform:none !important;
  display:block !important; margin:0 !important; padding:0 !important;
  background:transparent !important; border:0 !important; box-shadow:none !important;
  border-radius:inherit !important; outline:none !important;
  font-size:0 !important; line-height:0 !important; color:transparent !important; opacity:1 !important;
