/* ==========================================================
   10. 转账卡  橙色方角 · 白圈双箭头 · 金额在上 · "转账"在下 · 底部"微信转账"
   ========================================================== */
#chat-detail-screen .msg-transfer-card,
.chat-detail-screen .msg-transfer-card{
  position:relative !important; box-sizing:border-box !important;
  display:flex !important; flex-direction:column !important; justify-content:center !important;
  width:236px !important; min-width:236px !important; max-width:70vw !important;
  height:auto !important; min-height:72px !important;
  padding:10px 12px 46px 62px !important;
  border:0 !important; border-radius:var(--wx-radius) !important; box-shadow:none !important;
  overflow:visible !important; color:#ffffff !important; text-align:left !important;
  background:var(--wx-orange) url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40' fill='none' stroke='%23ffffff' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><circle cx='20' cy='20' r='18'/><polyline points='24 11 29 15.5 11 15.5'/><polyline points='16 29 11 24.5 29 24.5'/></svg>") no-repeat 12px 10px / 38px 38px !important;
}
#chat-detail-screen .msg-transfer-card:is(.msg-transfer-success, .msg-transfer-rejected, .msg-transfer-expired-card){
  background-color:var(--wx-orange-done) !important;
}
#chat-detail-screen .msg-transfer-card.msg-transfer-success{
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40' fill='none' stroke='%23ffffff' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><circle cx='20' cy='20' r='18'/><polyline points='12.5 20.5 18 26 28 15'/></svg>") !important;
}
/* 卡内所有层:间距清零 · 全部白字 */
#chat-detail-screen .msg-transfer-card *{
  min-height:0 !important; height:auto !important;
  margin:0 !important; padding:0 !important; gap:2px !important;
  background:transparent !important; border-color:transparent !important; box-shadow:none !important;
  color:#ffffff !important; -webkit-text-fill-color:#ffffff !important;
  font-family:-apple-system, BlinkMacSystemFont, "PingFang SC", "Helvetica Neue", sans-serif !important;
  font-style:normal !important; text-align:left !important; letter-spacing:0 !important; opacity:1 !important;
}
/* 中间包裹层摊平,让金额和"转账"能直接按顺序排 */
#chat-detail-screen .msg-transfer-card div:not(.msg-transfer-amount):not(.msg-transfer-subtitle):not(.msg-transfer-label):has(:is(.msg-transfer-amount, .msg-transfer-subtitle)){
  display:contents !important;
}
#chat-detail-screen .msg-transfer-card :is(svg, img, [class*="icon"], .msg-transfer-divider, .msg-transfer-chevron, .msg-transfer-check, .msg-transfer-status-text){ display:none !important; }
/* 金额:最上面 */
#chat-detail-screen .msg-transfer-card .msg-transfer-amount{
  order:1 !important; display:block !important;
  font-size:19px !important; line-height:23px !important; font-weight:500 !important;
}
/* "转账给 XX" → 只显示"转账" */
#chat-detail-screen .msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-subtitle{
  order:2 !important; display:block !important;
  font-size:0 !important; line-height:0 !important; color:transparent !important; -webkit-text-fill-color:transparent !important;
}
#chat-detail-screen .msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-subtitle > *{ display:none !important; }
#chat-detail-screen .msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-subtitle::after{
  content:"" !important; display:block;
  font-size:13px; line-height:17px; font-weight:400;
  color:#ffffff; -webkit-text-fill-color:#ffffff;
}
/* 右上角状态(已退回 / 已收款…) */
#chat-detail-screen .msg-transfer-card .msg-transfer-label{
  position:absolute !important; top:8px !important; right:10px !important; left:auto !important;
  font-size:12px !important; line-height:16px !important; font-weight:400 !important;
}
.chat-detail-screen .msg-transfer-card::before{
  content:"微信转账" !important; position:absolute !important;
  left:12px !important; right:12px !important; bottom:0 !important; top:auto !important;
  height:22px !important; line-height:22px !important;
  border-top:1px solid rgba(255,255,255,.35) !important;
  font-size:11px !important; color:rgba(255,255,255,.85) !important;
  background:none !important; pointer-events:none !important;
}
.chat-detail-screen .msg-transfer-card::after{
  content:"" !important; position:absolute !important;
  top:22px !important; left:-6px !important; right:auto !important;
  width:0 !important; height:0 !important;
  border-top:6px solid transparent !important; border-bottom:6px solid transparent !important;
  border-right:6px solid var(--wx-orange) !important; border-left:0 !important;
  pointer-events:none !important;
}
.chat-detail-screen .msg-transfer-card:is(.msg-transfer-success, .msg-transfer-rejected, .msg-transfer-expired-card)::after{ border-right-color:var(--wx-orange-done) !important; }
.chat-detail-screen .msg-me .msg-transfer-card::after{
  left:auto !important; right:-6px !important;
  border-right:0 !important; border-left:6px solid var(--wx-orange) !important;
}
.chat-detail-screen .msg-me .msg-transfer-card:is(.msg-transfer-success, .msg-transfer-rejected, .msg-transfer-expired-card)::after{ border-left-color:var(--wx-orange-done) !important; }

/* ==========================================================
   11. 红包  横排:左侧画出的红包(金圆+¥) · 右侧祝福语 · 左下角小字"红包"
   ========================================================== */
#chat-detail-screen .msg-transfer-card.msg-redpacket-card{
  display:flex !important; flex-direction:column !important; justify-content:center !important;
  width:236px !important; min-width:236px !important;
  min-height:0 !important;
  padding:12px 12px 46px 62px !important;
  background:var(--wx-red) url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 30 38'><rect x='0' y='0' width='30' height='38' rx='2' fill='%23F25C54'/><path d='M0 2a2 2 0 0 1 2-2h26a2 2 0 0 1 2 2v9c-4.5 3-9.5 4.5-15 4.5S4.5 14 0 11z' fill='%23E5484A'/><circle cx='15' cy='15' r='5.5' fill='%23F9C74F'/><path d='M12.6 12.4l2.4 2.6 2.4-2.6M15 15v4.2M12.8 16.4h4.4M12.8 18h4.4' fill='none' stroke='%23E5484A' stroke-width='1' stroke-linecap='round' stroke-linejoin='round'/></svg>") no-repeat 14px 10px / 30px 38px !important;
}
#chat-detail-screen .msg-transfer-card.msg-redpacket-card.is-opened{ background-color:var(--wx-orange-done) !important; }
#chat-detail-screen .msg-redpacket-card .msg-redpacket-emoji,
#chat-detail-screen .msg-redpacket-card .msg-transfer-label,
#chat-detail-screen .msg-redpacket-card .msg-transfer-amount{ display:none !important; }
#chat-detail-screen .msg-redpacket-card .msg-transfer-subtitle{
  display:block !important; font-size:16px !important; line-height:22px !important; font-weight:500 !important;
  white-space:nowrap !important; overflow:hidden !important; text-overflow:ellipsis !important;
}
.chat-detail-screen .msg-transfer-card.msg-redpacket-card::before{
  content:"红包" !important;
  left:14px !important; right:auto !important; bottom:4px !important;
  height:18px !important; line-height:18px !important;
  border-top:0 !important;
  font-size:11px !important; color:rgba(255,255,255,.85) !important;
}
.chat-detail-screen .msg-transfer-card.msg-redpacket-card::after{ top:22px !important; border-right-color:var(--wx-red) !important; }
.chat-detail-screen .msg-me .msg-transfer-card.msg-redpacket-card::after{ border-left-color:var(--wx-red) !important; }
.chat-detail-screen .msg-transfer-card.msg-redpacket-card.is-opened::after{ border-right-color:var(--wx-orange-done) !important; }
.chat-detail-screen .msg-me .msg-transfer-card.msg-redpacket-card.is-opened::after{ border-left-color:var(--wx-orange-done) !important; }

/* ==========================================================
   12. 礼物卡  240×100 · 图片背景 · 内容隐藏 · 深蓝尾巴
   ========================================================== */
:is(.msg-gift-card, .gift-ig-container){
  position:relative !important; box-sizing:border-box !important;
  width:240px !important; min-width:240px !important; max-width:70vw !important;
  height:100px !important; min-height:100px !important;
  padding:0 !important; margin:0 !important;
  border:0 !important; border-radius:var(--wx-radius) !important; box-shadow:none !important;
  overflow:visible !important;
  background:var(--wx-gift-img) center center / cover no-repeat !important;
  color:transparent !important; font-size:0 !important;
}
:is(.msg-gift-card, .gift-ig-container) > *{ display:none !important; }
:is(.msg-gift-card, .gift-ig-container)::before{ content:none !important; }
:is(.msg-gift-card, .gift-ig-container)::after{
  content:"" !important; position:absolute !important;
  top:28px !important; left:-6px !important; right:auto !important;
  width:0 !important; height:0 !important;
  border-top:6px solid transparent !important; border-bottom:6px solid transparent !important;
  border-right:6px solid var(--wx-gift-tail) !important; border-left:0 !important;
  pointer-events:none !important; z-index:1 !important;
}
.msg-me :is(.msg-gift-card, .gift-ig-container)::after{
  left:auto !important; right:-6px !important;
  border-right:0 !important; border-left:6px solid var(--wx-gift-tail) !important;
}

/* ==========================================================
   13. 图片(仅我方)  3:4 主图 + 后叠两张倾斜小图 + 左侧"展开 3"
   ========================================================== */
.msg-me :is(.msg-image-card, .msg-image-wrapper){
  position:relative !important; isolation:isolate !important; box-sizing:border-box !important;
  width:var(--wx-img-w) !important; max-width:var(--wx-img-w) !important;
  height:auto !important; aspect-ratio:3 / 4 !important;
  margin-right:var(--wx-img-shift) !important; padding:0 !important;
  background:transparent !important; border:0 !important; box-shadow:none !important;
  border-radius:6px !important; overflow:visible !important;
}
.msg-me :is(.msg-image-card, .msg-image-wrapper) > :not(.live-photo-badge){
  width:100% !important; height:100% !important; max-width:none !important; max-height:none !important;
  border-radius:6px !important; overflow:hidden !important;
}
.msg-me :is(.msg-image-card, .msg-image-wrapper) img{
  display:block !important; width:100% !important; height:100% !important;
  max-width:none !important; max-height:none !important;
  aspect-ratio:3 / 4 !important; object-fit:cover !important;
  border-radius:6px !important; box-shadow:0 2px 8px rgba(0,0,0,.10) !important;
}
.msg-me :is(.msg-image-card, .msg-image-wrapper)::before{
  content:"" !important; position:absolute !important;
  top:5% !important; right:-6px !important; width:90% !important; height:90% !important;
  background:var(--wx-stack-1) center / cover no-repeat !important;
  border-radius:5px !important;
  transform:rotate(4deg) !important; transform-origin:left center !important;
  box-shadow:0 1px 4px rgba(0,0,0,.10) !important;
  pointer-events:none !important; z-index:-1 !important;
}
.msg-me :is(.msg-image-card, .msg-image-wrapper)::after{
  content:"" !important; position:absolute !important;
  top:10% !important; right:-12px !important; width:80% !important; height:80% !important;
  background:var(--wx-stack-2) center / cover no-repeat !important;
  border-radius:4px !important;
  transform:rotate(8deg) !important; transform-origin:left center !important;
  box-shadow:0 1px 4px rgba(0,0,0,.10) !important;
  pointer-events:none !important; z-index:-2 !important;
}
.msg-me .msg-content-stack:has(.msg-image-card, .msg-image-wrapper)::before{
  content:"展开 3" !important; position:absolute !important;
  top:50% !important; right:calc(100% + 10px) !important; left:auto !important;
  transform:translateY(-50%) !important;
  padding:4px 11px !important;
  background:var(--wx-pill) !important; border:0 !important; border-radius:999px !important;
  color:var(--wx-gray-dk) !important; font-size:12px !important; font-weight:500 !important; line-height:1.2 !important;
  white-space:nowrap !important; pointer-events:none !important; z-index:3 !important;
}
.msg-them :is(.msg-image-card, .msg-image-wrapper),
.msg-them :is(.msg-image-card, .msg-image-wrapper) img{ border-radius:6px !important; }

/* ==========================================================
   14. 底栏  独立磨砂背板(只透颜色) · 底部留出安全区再上移 12px
            [语音圈] [输入框|麦克风] [表情] [加号] [发送]
   ========================================================== */
#chat-detail-screen .input-area-custom,
.chat-detail-screen .input-area-custom{
  box-sizing:border-box !important;
  padding-bottom:calc(env(safe-area-inset-bottom, 0px) + var(--wx-bar-lift)) !important;
  background:transparent !important; background-image:none !important;
  -webkit-backdrop-filter:none !important; backdrop-filter:none !important;
  border-top:0 !important; box-shadow:none !important;
}
/* 磨砂背板 */
#chat-detail-screen .input-area-custom::before,
.chat-detail-screen .input-area-custom::before{
  content:"" !important; display:block !important;
  position:absolute !important; inset:0 !important;
  background:var(--wx-bar) !important;
  -webkit-backdrop-filter:var(--wx-blur) !important; backdrop-filter:var(--wx-blur) !important;
  border-top:.5px solid var(--wx-line) !important;
  pointer-events:none !important; z-index:-1 !important;
}
.chat-detail-screen .input-area-custom::after{ content:none !important; }
