}
div.chat-detail-screen .msg-transfer-card.msg-transfer-success:not(.msg-redpacket-card) .msg-transfer-status-text::after,
div.chat-detail-screen .msg-transfer-card.msg-transfer-rejected:not(.msg-redpacket-card) .msg-transfer-status-text::after,
div.chat-detail-screen .msg-transfer-card.msg-transfer-expired-card:not(.msg-redpacket-card) .msg-transfer-status-text::after {
