/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【红包】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* ═══════════════════════════════════════════════
   红包卡片 · 仿 QQ 竖版红包
   - 红包图片直接铺在卡片背景上，原生的 🧧、标题、祝福语、金额、「开」全部隐藏
   - 「開」下面显示状态文字：已领取 / 已被领取 / 已退回 / 已过期（未拆封不显示）
   - 未拆封：保持红色，没有动画
   - 已领取 / 已退回 / 已过期：0.6 秒内渐变成灰色
   - 卡片左下方显示灰色小标签「普通红包」
   尺寸：卡片 150 × 225（2:3）
   按 P2 测量：「開」圆心在卡片高度 78%，状态文字中心在 92%
   ═══════════════════════════════════════════════ */

div.chat-detail-screen {
    /* 🐕 */ --rp-w: 150px;              /* ← 红包宽度 */
    /* 🐕 */ --rp-h: 225px;              /* ← 红包高度（宽 × 1.5） */
    /* 🐕 */ --rp-img: url("https://i.postimg.cc/T17rgPLG/IMG-5610.jpg");
    /* 🐕 */ --rp-status-top: 92%;       /* ← 状态文字中心的高度位置 */
    /* 🐕 */ --rp-text-display: none;    /* ← 图片上没有祝福语时改成 block */
}

/* --- 0. 去掉外层古早气泡壳 --- */
div.chat-detail-screen .bubble-me-custom:has(.msg-redpacket-card),
div.chat-detail-screen .msg-plain-me:has(.msg-redpacket-card),
div.chat-detail-screen .bubble-them-custom:has(.msg-redpacket-card),
div.chat-detail-screen .msg-plain-them:has(.msg-redpacket-card) {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
}
div.chat-detail-screen .bubble-me-custom:has(.msg-redpacket-card)::before,
div.chat-detail-screen .bubble-me-custom:has(.msg-redpacket-card)::after,
div.chat-detail-screen .msg-plain-me:has(.msg-redpacket-card)::before,
div.chat-detail-screen .msg-plain-me:has(.msg-redpacket-card)::after,
div.chat-detail-screen .bubble-them-custom:has(.msg-redpacket-card)::before,
div.chat-detail-screen .bubble-them-custom:has(.msg-redpacket-card)::after,
div.chat-detail-screen .msg-plain-them:has(.msg-redpacket-card)::before,
div.chat-detail-screen .msg-plain-them:has(.msg-redpacket-card)::after {
    display: none !important;
}

/* --- 1. 卡片本体：红包图片做背景 --- */
div.chat-detail-screen .msg-redpacket-card {
    display: block !important;
    position: relative !important;
    width: var(--rp-w) !important;
    height: var(--rp-h) !important;
    min-width: 0 !important;
    min-height: 0 !important;
    margin: 0 0 30px 0 !important;      /* 底部留给「普通红包」标签 */
    padding: 0 !important;
    box-sizing: border-box !important;
    background: var(--rp-img) center / cover no-repeat !important;
    border: none !important;
    border-radius: 8px !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.12) !important;
    overflow: visible !important;       /* 标签在卡片外面，不能裁 */
    filter: none !important;
    animation: none !important;
    transform: none !important;
    cursor: pointer !important;
    -webkit-tap-highlight-color: transparent !important;
}

/* --- 2. 原生内容全部隐藏（不挡点击，点卡片照样能拆） --- */
div.chat-detail-screen .msg-redpacket-card * {
    visibility: hidden !important;
}

/* --- 3. 「開」下面的状态文字 --- */
div.chat-detail-screen .msg-redpacket-card::before {
    content: "已领取" !important;       /* 已拆封的默认文案 */
    display: block !important;
    position: absolute !important;
    z-index: 2 !important;
    left: 0 !important;
    right: 0 !important;
    top: calc(var(--rp-status-top) - 8px) !important;   /* 行高 16 的一半 */
    bottom: auto !important;
    width: auto !important;
    height: 16px !important;
    margin: 0 !important;
    padding: 0 !important;
    background: none !important;
    border: none !important;
    box-shadow: none !important;
    text-align: center !important;
    font-size: 12px !important;
    font-weight: 500 !important;
    line-height: 16px !important;
    letter-spacing: 1px !important;
    color: #FFE2B0 !important;          /* 和「恭喜发财」同色 */
    text-shadow: none !important;
    white-space: nowrap !important;
    visibility: visible !important;
    pointer-events: none !important;
}

/* 未拆封：不显示状态文字 */
div.chat-detail-screen .msg-redpacket-card.is-unopened::before {
    content: none !important;
    display: none !important;
}

/* 我发的红包被对方领了 */
div.chat-detail-screen .msg-me .msg-redpacket-card.is-opened::before {
    content: "已被领取" !important;
}

/* 已退回 / 已过期（写在后面，优先级相同时后写的生效） */
div.chat-detail-screen .msg-redpacket-card.msg-transfer-rejected:not(.is-unopened)::before {
    content: "已退回" !important;
}
div.chat-detail-screen .msg-redpacket-card.msg-transfer-expired-card:not(.is-unopened)::before {
    content: "已过期" !important;
}

/* --- 4. 已领取 / 已退回 / 已过期：浅灰 --- */
div.chat-detail-screen .msg-redpacket-card:not(.is-unopened),
div.chat-detail-screen .msg-redpacket-card.msg-transfer-rejected,
div.chat-detail-screen .msg-redpacket-card.msg-transfer-expired-card {
    filter: grayscale(0.55) brightness(1.08) !important;   /* ← 灰的程度 */
    animation: rp-to-gray 0.6s ease-out both !important;
}

@keyframes rp-to-gray {
    from { filter: grayscale(0) brightness(1); }
    to   { filter: grayscale(0.55) brightness(1.08); }      /* ← 要和上面一致 */
}

/* --- 5. 「普通红包」标签：卡片左下方 --- */
div.chat-detail-screen .msg-redpacket-card::after {
    content: "普通红包" !important;
    display: block !important;
    position: absolute !important;
    top: calc(100% + 6px) !important;
    left: 0 !important;
    right: auto !important;
    bottom: auto !important;
    width: auto !important;
    height: auto !important;
    margin: 0 !important;
    padding: 3px 9px !important;
    background: #DCDCDC !important;
    border: none !important;
    border-radius: 10px !important;
    box-shadow: none !important;
    font-size: 11px !important;
    font-weight: 400 !important;
    line-height: 14px !important;
    color: #FFFFFF !important;
    text-shadow: none !important;
    white-space: nowrap !important;
    visibility: visible !important;
    pointer-events: none !important;
}

/* --- 6. 可选：把 App 的祝福语叠到图片上（默认关闭，见 --rp-text-display） --- */
div.chat-detail-screen .msg-redpacket-card .msg-transfer-subtitle {
    display: var(--rp-text-display) !important;
    visibility: visible !important;
    position: absolute !important;
    z-index: 2 !important;
    left: 10px !important;
    right: 10px !important;
    top: 44% !important;
    margin: 0 !important;
    padding: 0 !important;
    text-align: center !important;
    font-size: 15px !important;
    font-weight: 500 !important;
    line-height: 20px !important;
    color: #FFE2B0 !important;
    text-shadow: none !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    pointer-events: none !important;
}

/* 系统开了「减少动态效果」时直接变灰，不播渐变 */
@media (prefers-reduced-motion: reduce) {
    div.chat-detail-screen .msg-redpacket-card {
        animation: none !important;
    }
}
/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【文字长图卡】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* ═══════════════════════════════════════════════
   文字长图卡 .msg-sim-card · 5 张倾斜叠放 + 点按换图 + 浅灰胶囊
   ───────────────────────────────────────────────
   外层气泡宽 260（我方从左到右）：
     胶囊 0~60 | 间隔 10 | 前卡 70~220 | 牌堆 220~260
   对方镜像：牌堆 0~40 | 前卡 40~190 | 间隔 10 | 胶囊 200~260
   图层（坐标相对前卡左上角，我方；对方左右镜像）
     L1 前卡   card::before      x 0~150   y 0~200   0°
     L2        card::after       x 14~160  y 3~197   1.5°  z -1
     L3        divider::before   x 26~168  y 6~194   3°    z -2
     L4        date::before      x 37~175  y 9~191   4.5°  z -3
     L5        气泡::before      x 47~181  y 12~188  6°    z -4
   点按区（前卡内，从左到右）
     卡片本身 0~60 → 第2张 | divider 60~90 → 第3张
     date 90~120 → 第4张   | 地点 120~150 → 第5张
   胶囊：外观画在气泡 ::after，.msg-sim-text 做透明点按层盖在上面
   ═══════════════════════════════════════════════ */

/* --- 0. 变量 + 外层气泡去壳 --- */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) {
    /* 🐕 */ --sim-a: url("https://i.postimg.cc/T1dwj8Bs/IMG-5626.png");
    /* 🐕 */ --sim-b: url("https://i.postimg.cc/8cZCtKS8/IMG-5627.png");
    /* 🐕 */ --sim-c: url("https://i.postimg.cc/KjGz7Xdy/IMG-5628.jpg");
    /* 🐕 */ --sim-d: url("https://i.postimg.cc/zvzBwm95/IMG-5629.jpg");
    /* 🐕 */ --sim-e: url("https://i.postimg.cc/1Xmt0xLm/IMG-5630.jpg");
    /* 🐕 */ --l1: var(--sim-a);
    /* 🐕 */ --l2: var(--sim-b);
    /* 🐕 */ --l3: var(--sim-c);
    /* 🐕 */ --l4: var(--sim-d);
    /* 🐕 */ --l5: var(--sim-e);
    /* 🐕 */ --tilt: 1.5deg;      /* ← 每层多歪的角度 */
    /* 🐕 */ --dir: 1;            /* 1 往右叠，-1 往左叠 */

    position: relative !important;
    isolation: isolate !important;
    width: fit-content !important;
    max-width: none !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    overflow: visible !important;
}
div.chat-detail-screen :is(.bubble-them-custom, .msg-plain-them):has(.msg-sim-card) {
    /* 🐕 */ --dir: -1;
}

/* --- 1. 五个图层的公共样式 --- */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card)::before,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card::before,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card::after,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card > .msg-sim-divider::before,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card > .msg-sim-date::before {
    content: "" !important;
    display: block !important;
    position: absolute !important;
    right: auto !important;
    bottom: auto !important;
    box-sizing: border-box !important;
    margin: 0 !important;
    padding: 0 !important;
    border: none !important;
    border-radius: 10px !important;
    background-color: #DDDDDD !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    box-shadow: 0 0 0 0.5px rgba(0, 0, 0, 0.15), 0 1px 3px rgba(0, 0, 0, 0.10) !important;
    transform-origin: center !important;
    transform: rotate(var(--rot)) !important;
    opacity: 1 !important;
    visibility: visible !important;
    font-size: 0 !important;
    pointer-events: none !important;
}

/* L1 前卡 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card::before {
    /* 🐕 */ --rot: 0deg;
    left: 0 !important;
    top: 0 !important;
    width: 150px !important;
    height: 200px !important;
    z-index: auto !important;
    background-image: var(--l1) !important;
}
/* L2 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card::after {
    /* 🐕 */ --rot: calc(var(--tilt) * 1 * var(--dir));
    left: 14px !important;
    top: 3px !important;
    width: 146px !important;
    height: 194px !important;
    z-index: -1 !important;
    background-image: var(--l2) !important;
}
/* L3（挂在 divider 上，divider 在 x=60，所以 26−60 = −34） */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card > .msg-sim-divider::before {
    /* 🐕 */ --rot: calc(var(--tilt) * 2 * var(--dir));
    left: -34px !important;
    top: 6px !important;
    width: 142px !important;
    height: 188px !important;
    z-index: -2 !important;
    background-image: var(--l3) !important;
}
/* L4（挂在 date 上，date 在 x=90，所以 37−90 = −53） */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card > .msg-sim-date::before {
    /* 🐕 */ --rot: calc(var(--tilt) * 3 * var(--dir));
    left: -53px !important;
    top: 9px !important;
    width: 138px !important;
    height: 182px !important;
    z-index: -3 !important;
    background-image: var(--l4) !important;
}
/* L5（挂在外层气泡上；我方前卡在气泡 x=70，70+47 = 117） */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card)::before {
    /* 🐕 */ --rot: calc(var(--tilt) * 4 * var(--dir));
    left: 117px !important;
    top: 12px !important;
    width: 134px !important;
    height: 176px !important;
    z-index: -4 !important;
    background-image: var(--l5) !important;
}

/* 对方：图层往左，镜像坐标 */
div.chat-detail-screen :is(.bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card::after {
    left: -10px !important;
}
div.chat-detail-screen :is(.bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card > .msg-sim-divider::before {
    left: -78px !important;
}
div.chat-detail-screen :is(.bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card > .msg-sim-date::before {
    left: -115px !important;
}
div.chat-detail-screen :is(.bubble-them-custom, .msg-plain-them):has(.msg-sim-card)::before {
    left: 9px !important;   /* 对方前卡在气泡 x=40，40 − 31 = 9 */
}

/* --- 2. 前卡本体：透明，只当定位基准和点按区 --- */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card {
    display: block !important;
    position: relative !important;
    z-index: auto !important;
    width: 150px !important;
    height: 200px !important;
    min-width: 0 !important;
    min-height: 0 !important;
    max-width: none !important;
    max-height: none !important;
    padding: 0 !important;
    box-sizing: border-box !important;
    background: transparent !important;
    border: none !important;
    border-radius: 10px !important;
    box-shadow: none !important;
    overflow: visible !important;
    transform: none !important;
    filter: none !important;
    opacity: 1 !important;
    cursor: pointer !important;
    -webkit-tap-highlight-color: transparent !important;
}
/* 我方：左边 70 给胶囊，右边 40 给牌堆 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me):has(.msg-sim-card) .msg-sim-card {
    margin: 0 40px 0 70px !important;
}
/* 对方：左边 40 给牌堆，右边 70 给胶囊 */
div.chat-detail-screen :is(.bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card {
    margin: 0 70px 0 40px !important;
}

/* --- 3. 卡片里的元素：全部变成透明竖条（不能用 opacity/transform，否则图层会跑到前卡上面） --- */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card > * {
    display: block !important;
    position: absolute !important;
    top: 0 !important;
    bottom: auto !important;
    left: 0 !important;
    right: auto !important;
    width: 0 !important;
    height: 200px !important;
    min-width: 0 !important;
    max-width: none !important;
    margin: 0 !important;
    padding: 0 !important;
    background: transparent !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    font-size: 0 !important;
    line-height: 0 !important;
    color: transparent !important;
    text-shadow: none !important;
    transform: none !important;
