/* 不当图层的伪元素清掉 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card > .msg-sim-divider::after,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card > .msg-sim-date::after,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card > :not(.msg-sim-text, .msg-sim-date, .msg-sim-divider)::before,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card > :not(.msg-sim-text, .msg-sim-date, .msg-sim-divider)::after {
