/* --- 4. 点按换图：每个状态把 5 张图轮换一位 --- */
/* 点卡片左边 → 第 2 张 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card:hover):not(:has(.msg-sim-text:hover)) {
    /* 🐕 */ --l1: var(--sim-b); --l2: var(--sim-c); --l3: var(--sim-d); --l4: var(--sim-e); --l5: var(--sim-a);
}
/* 点 60~90 → 第 3 张 */
