}
/* 点 120~150 → 第 5 张 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card > :not(.msg-sim-text, .msg-sim-date, .msg-sim-divider):hover):not(:has(.msg-sim-text:hover)) {
    /* 🐕 */ --l1: var(--sim-e); --l2: var(--sim-a); --l3: var(--sim-b); --l4: var(--sim-c); --l5: var(--sim-d);
}

/* --- 5. 换图动画：从牌堆那侧滑入 + 由淡变实） --- */
/* 每个状态用不同名字，切换时动画才会重新播放 */
@keyframes sim-cut-2 {
    from { transform: translateX(calc(9px * var(--dir))) scale(0.978) rotate(var(--rot)); opacity: 0.4; }
    to   { transform: rotate(var(--rot)); opacity: 1; }
}
@keyframes sim-cut-3 {
    from { transform: translateX(calc(9px * var(--dir))) scale(0.978) rotate(var(--rot)); opacity: 0.4; }
    to   { transform: rotate(var(--rot)); opacity: 1; }
}
@keyframes sim-cut-4 {
    from { transform: translateX(calc(9px * var(--dir))) scale(0.978) rotate(var(--rot)); opacity: 0.4; }
    to   { transform: rotate(var(--rot)); opacity: 1; }
}
@keyframes sim-cut-5 {
    from { transform: translateX(calc(9px * var(--dir))) scale(0.978) rotate(var(--rot)); opacity: 0.4; }
    to   { transform: rotate(var(--rot)); opacity: 1; }
}

div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card::before,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card::after {
