}
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card:hover):not(:has(.msg-sim-text:hover)) .msg-sim-card::before,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card:hover):not(:has(.msg-sim-text:hover)) .msg-sim-card::after {
    animation-name: sim-cut-2 !important;
}
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-divider:hover):not(:has(.msg-sim-text:hover)) .msg-sim-card::before,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-divider:hover):not(:has(.msg-sim-text:hover)) .msg-sim-card::after {
    animation-name: sim-cut-3 !important;
}
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-date:hover):not(:has(.msg-sim-text:hover)) .msg-sim-card::before,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-date:hover):not(:has(.msg-sim-text:hover)) .msg-sim-card::after {
    animation-name: sim-cut-4 !important;
}
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card > :not(.msg-sim-text, .msg-sim-date, .msg-sim-divider):hover):not(:has(.msg-sim-text:hover)) .msg-sim-card::before,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card > :not(.msg-sim-text, .msg-sim-date, .msg-sim-divider):hover):not(:has(.msg-sim-text:hover)) .msg-sim-card::after {
