/* --- 6b. .msg-sim-text：透明点按层，正好盖在胶囊上 --- */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card .msg-sim-text {
