    right: auto !important;
}
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card .msg-sim-text::before,
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card .msg-sim-text::after {
    content: none !important;
    display: none !important;
}

/* 点胶囊：展开成浅灰文字框，盖住胶囊，显示图片文字 */
div.chat-detail-screen :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-sim-card) .msg-sim-card .msg-sim-text:hover {
    width: max-content !important;
