    -webkit-backdrop-filter: none !important;
}
html body .nuo-forum-root:has(.nuo-forum-profile) .nuo-forum-chrome-header .forum-title {
    display: none !important;
}

/* ========================================
   「我的」页面 / 他人主页 布局
   从上到下：背景图 → 头像居中压边 → 名字+等级（居中）→ 按钮
   ======================================== */

/* 资料区：上面留出背景图高度（190px）+ 头像下半截的空间 */
.nuo-forum-root .profile-header {
    position: relative !important;
    overflow: visible !important;
    box-sizing: border-box !important;
    padding: 214px 20px 18px 20px !important;   /* 214 = 背景图190 + 24 */
    background-image: none !important;
}

/* 背景图本体：固定高度、铺满、居中 */
.nuo-forum-root .profile-header::before {
    content: "" !important;
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    height: 190px !important;                    /* 背景图高度 */
    z-index: 0 !important;
    pointer-events: none !important;

    /* 第一层：你的图；第二层：图加载失败时显示的深灰渐变 */
    background-image: var(--forum-profile-header-bg-image), linear-gradient(135deg, #3a3a42 0%, #1c1c22 100%) !important;
    background-size: cover, cover !important;
    background-position: center, center !important;
    background-repeat: no-repeat, no-repeat !important;
}

/* 头像：水平居中，压在背景图下边缘（只固定头像本身） */
.nuo-forum-root .profile-header > .nuo-forum-me-avatar,
.nuo-forum-root .profile-header > .nuo-forum-profile-avatar,
.nuo-forum-root .profile-header > *:has(> .nuo-forum-me-avatar),
.nuo-forum-root .profile-header > *:has(> .nuo-forum-profile-avatar),
.nuo-forum-root .profile-header > *:first-child:not(.profile-name-row):not(.profile-actions-row) {
    position: absolute !important;
    left: 50% !important;
    right: auto !important;
    top: 148px !important;           /* = 背景图高度190 - 头像一半42，数字越小压得越多 */
    bottom: auto !important;
    margin: 0 0 0 -42px !important;  /* -42 = 头像宽度一半，保证居中 */
    width: 84px !important;
    height: 84px !important;
    z-index: 5 !important;
    transform: none !important;
    border-radius: 28% !important;
    overflow: hidden !important;
}

/* 他人主页：头像改成正圆，里面那层撑满 */
html body .nuo-forum-root:has(.nuo-forum-profile) .profile-header > .nuo-forum-me-avatar,
