/* 朋友圈彻底去小三角 + 评论区/被回复人名字全变纯白 */

/* 彻底隐藏顶部小三角伪元素（全维度定位精准清理） */
.nj-moments-engagement::before,
.nj-moments-engagement::after,
.nj-moments-likes::before,
.nj-moments-likes::after,
.nj-moments-comment::before,
.nj-moments-comment::after,
#messaging-moments-tab .nj-moments-engagement::before,
#messaging-moments-tab .nj-moments-engagement::after,
#messaging-moments-tab .nj-moments-likes::before,
#messaging-moments-tab .nj-moments-likes::after,
#messaging-moments-tab .nj-moments-comment::before,
#messaging-moments-tab .nj-moments-comment::after,
#messaging-moments-tab [class*="arrow"],
#messaging-moments-tab [class*="triangle"] {
  display: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
  border: none !important;
  border-color: transparent !important;
  width: 0 !important;
  height: 0 !important;
}

/* 评论区底色保持暗黑 */
[data-color-scheme="dark"] .nj-moments-engagement,
[data-color-scheme="dark"] .nj-moments-comment {
  background-color: #1c1c1e !important;
  background: #1c1c1e !important;
  border: none !important;
  box-shadow: none !important;
}

/* 评论区所有名字（发布人、被回复人、点赞人）强制纯白 */
[data-color-scheme="dark"] .nj-moments-post-name,
[data-color-scheme="dark"] .nj-moments-comment-author,
[data-color-scheme="dark"] .nj-moments-engagement a,
[data-color-scheme="dark"] .nj-moments-comment a,
[data-color-scheme="dark"] .nj-moments-comment span,
[data-color-scheme="dark"] .nj-moments-comment div,
[data-color-scheme="dark"] .nj-moments-comment [class*="reply"],
[data-color-scheme="dark"] .nj-moments-comment [class*="target"],
[data-color-scheme="dark"] .nj-moments-comment [class*="user"],
[data-color-scheme="dark"] .nj-moments-likes,
[data-color-scheme="dark"] .nj-moments-likes * {
  color: #ffffff !important;
}

/* 动态正文与评论正文 */
