[data-color-scheme="dark"] .nj-moments-comment-content {
  color: #e5e5e7 !important;
}

[data-color-scheme="dark"] .nj-moments-post-time {
  color: #8e8e93 !important;
}

[data-color-scheme="dark"] .nj-chat-tab-header-edit > *:not(svg):not(img) {
  /* 这里的颜色会无视上方的日间设置，在深色模式下强制生效 */
  background: #000000 !important;       /* 背景 */
  border: 1.5px solid #ffffff !important; /*描边*/
  color: #ffffff !important;            /* 白色字体 */
}

/* --- 深色模式：头像角标与底栏未读点适配 --- */
