}

.rs-stitle,
.rs-facts {
  width: 100% !important;
  max-width: 420px !important;
  box-sizing: border-box !important;
  background: var(--rs-card-bg) !important;
  backdrop-filter: var(--rs-card-blur) !important;
  -webkit-backdrop-filter: var(--rs-card-blur) !important;
}

/* 标题 = 卡片上半。原文字藏掉，用 ::before 写「基本资料」 */
.rs-stitle {
  display: block !important;
  padding: 22px 22px 14px !important;
  border: 1px solid var(--rs-card-border) !important;
  border-bottom: none !important;
  border-radius: 16px 16px 0 0 !important;
  font-size: 0 !important;
  color: transparent !important;
  writing-mode: horizontal-tb !important;
  text-orientation: mixed !important;
}

.rs-stitle::before {
  content: "基本资料" !important;
  display: inline-block !important;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Arial, sans-serif !important;
  font-size: 22px !important;
  font-weight: 600 !important;
  color: var(--rs-text) !important;
  letter-spacing: 0 !important;
}

.rs-stitle small {
  font-size: 0 !important;
  color: transparent !important;
