/*⁣​‌‌‍‍​⁠‌‌​​‍⁠⁠‍​‌​​⁠‌‌‍​​‍‍‌​​​‍⁠‌⁠​⁠‌⁠‍‌‍‍‌‌⁠⁠⁠‍‍‍⁠​⁠‌‌‍⁠⁠‌‍‍‌​⁣⁣​​‌​​​‍‌‍⁠​‌‍​​‍⁠‌​‌‍​​​‌⁠​‍​‌‌⁠​‌​⁠‌‌‌‍‌​‌‍‌‌‌‍⁠⁠⁠‌​⁠⁠‍‍​‍⁠‌‍‍⁠⁣ 名册与公开标签 */
.roster-app-container {
  color: var(--pc-ink) !important;
  background: var(--pc-paper) center / cover no-repeat !important;
}
/* 菜单存在时淡入全屏蒙罩，关闭后淡出。只覆盖视觉，保留应用点击逻辑。 */
.roster-app-container::after {
  content: "" !important;
  display: block !important;
  position: fixed !important;
  box-sizing: border-box !important;
  inset: 0 !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: rgba(34,27,48,.38) !important;
  box-shadow: none !important;
  filter: none !important;
  transform: none !important;
  animation: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
  transition: opacity .22s ease,visibility 0s linear .22s !important;
  z-index: 900 !important;
}
.roster-app-container:has(.fab-popup-text)::after {
  opacity: 1 !important;
  visibility: visible !important;
  transition-delay: 0s !important;
}
.roster-theme-guofeng > .roster-stardust {
  display: none !important;
}
.roster-title {
  color: var(--pc-ink) !important;
  font-family: var(--pc-font) !important;
  letter-spacing: .12em !important;
  text-shadow: 0 1px 0 #fff !important;
}
.category-pill {
  color: var(--pc-ink-2) !important;
  border-color: #d5bd9c !important;
  background: linear-gradient(140deg,#fffdf9,#f2ecef) !important;
  box-shadow: 0 2px 6px #5e3e6518 !important;
}
.category-pill.active {
  color: var(--pc-ink) !important;
  border-color: var(--pc-gold) !important;
  background: linear-gradient(140deg,#faf5ff,#dcd0ec) !important;
  box-shadow: inset 0 0 0 2px #ffffff80 !important;
}
.roster-search-bar {
  color: var(--pc-ink-2) !important;
  border-color: #d4c0a6 !important;
  background: #fffcf8e8 !important;
}
.rj-name span {
  color: var(--pc-ink) !important;
  font-family: var(--pc-font) !important;
  letter-spacing: .1em !important;
}
.rj-tassel,.rj-chain {
  display: none !important;
}
.rj-sway {
  animation: none !important;
}

/* 详情背景；保留原画卷镜头 */
.rs-overlay,.rg-hall,.roster-tarot-detail {
  color: var(--pc-ink) !important;
  background: var(--pc-paper) center / cover no-repeat !important;
}
.rs-world img {
  content: var(--pc-world) !important;
}
.rs-top {
  color: var(--pc-ink) !important;
}
.rs-ib,.rjs-act {
  color: var(--pc-ink) !important;
  border-color: #c6a06c !important;
  background: radial-gradient(circle at 35% 25%,#fffdfb,#ece2f1) !important;
  box-shadow: inset 0 0 0 2px #fff9ef99 !important;
}
.rs-nav {
  color: var(--pc-gold) !important;
}
.rs-hero,.rs-mini {
  border-color: #c6a06c !important;
  box-shadow: 0 4px 14px #3c2d491f !important;
}
.rs-name,.rg-title h2,.rjs-title h2 {
  color: var(--pc-ink) !important;
  font-family: var(--pc-font) !important;
  letter-spacing: .08em !important;
  text-shadow: 0 1px 0 #fff !important;
}
.rs-role,.rjs-tags span {
  color: var(--pc-ink-2) !important;
  border-color: #c8b3d6 !important;
  background: linear-gradient(140deg,#fbf8fe,#e5dbef) !important;
}
.rs-seal {
  color: #a57c43 !important;
  border-color: #c6a06c !important;
}
.rs-stitle {
  color: var(--pc-ink) !important;
  font-family: var(--pc-font) !important;
  border-color: #d9c39e !important;
  background-color: #fbf8f0ee !important;
}
.rs-fact {
  color: var(--pc-ink-2) !important;
  border-color: #ddcbae !important;
  background: linear-gradient(120deg,#fffdf9e8,#ebe2f1dc) !important;
}
.rs-colophon-text {
  color: var(--pc-ink) !important;
  font-family: var(--pc-font) !important;
  text-shadow: none !important;
}
.rs-slip {
  color: var(--pc-ink) !important;
  border-color: #c6a06c !important;
  background: linear-gradient(120deg,#fffaf3,#e9e0f2) !important;
  box-shadow: 0 3px 9px #5d45651a !important;
}
.rs-sheet,.rjs-paper {
  color: var(--pc-ink) !important;
  font-family: var(--pc-font) !important;
  border-color: #c6a06c !important;
  background: var(--pc-paper) center / cover no-repeat !important;
}
.rs-coda {
  color: var(--pc-ink-2) !important;
  border-color: #ddcbae !important;
  background-color: #fffaf2e8 !important;
}

/* 卡片布局：网格与轮播，轮播位置和翻牌变换由应用继续管理。 */
.character-grid {
  display: grid !important;
  grid-template-columns: repeat(var(--pc-grid-columns),minmax(0,1fr)) !important;
  gap: 18px var(--pc-grid-gap) !important;
  align-items: start !important;
  align-content: start !important;
  box-sizing: border-box !important;
  width: 100% !important;
  max-width: 780px !important;
  height: auto !important;
  min-height: 0 !important;
  margin: 0 auto !important;
  padding: 18px 14px 96px !important;
}
:is(.character-grid,.carousel-item) > .premium-card {
  position: relative !important;
  box-sizing: border-box !important;
  width: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: none !important;
  max-height: none !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-image: none !important;
  outline: 0 !important;
  border-radius: 4% / 2.2857% !important;
  background: transparent !important;
  box-shadow: none !important;
  filter: drop-shadow(0 4px 8px #4b31552b) !important;
  overflow: visible !important;
  clip-path: none !important;
  -webkit-mask: none !important;
  mask: none !important;
}
.character-grid > .premium-card {
  height: auto !important;
  aspect-ratio: 4 / 7 !important;
  transform: none !important;
}
.carousel-item > .premium-card {
  height: 100% !important;
  aspect-ratio: auto !important;
}
.premium-card > .flip-card-inner {
  position: relative !important;
  box-sizing: border-box !important;
  width: 100% !important;
  height: 100% !important;
  border: 0 !important;
  outline: 0 !important;
  border-radius: inherit !important;
  background: transparent !important;
  box-shadow: none !important;
  transform-style: preserve-3d !important;
}
.premium-card > .flip-card-inner > :is(.flip-card-front,.flip-card-back) {
  position: absolute !important;
  box-sizing: border-box !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
  border: 0 !important;
  outline: 0 !important;
  border-radius: inherit !important;
  box-shadow: none !important;
  -webkit-backface-visibility: hidden !important;
  backface-visibility: hidden !important;
}
.premium-card > .flip-card-inner > .flip-card-front {
  background: transparent !important;
  overflow: visible !important;
  clip-path: none !important;
  -webkit-mask: none !important;
  mask: none !important;
}
.premium-card > .flip-card-inner > .flip-card-back {
  background: var(--pc-drawn-back) center / 100% 100% no-repeat !important;
  overflow: hidden !important;
}

/* 透明绘制金框：直接装在现有 card-border；下沿允许向外延伸。 */
.character-grid > .premium-card > .card-border,
.carousel-item > .premium-card > .flip-card-inner > .flip-card-front > .card-border {
  position: absolute !important;
  box-sizing: border-box !important;
  display: block !important;
  inset: 0 0 auto 0 !important;
  width: 100% !important;
  height: 102.4% !important;
  min-height: 0 !important;
  max-height: none !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-image: none !important;
  border-radius: inherit !important;
  background: var(--pc-drawn-front) center top / 100% 100% no-repeat !important;
  box-shadow: none !important;
  transform: none !important;
  opacity: 1 !important;
  pointer-events: none !important;
  z-index: 2 !important;
}
.character-grid > .premium-card > .card-content,
.carousel-item > .premium-card > .flip-card-inner > .flip-card-front > .card-content {
  position: absolute !important;
  box-sizing: border-box !important;
  inset: 1.5% 2.625% 1.5% !important;
  width: auto !important;
  height: auto !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: none !important;
  max-height: none !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 2.5% / 1.4286% !important;
  background: #292039 !important;
  overflow: hidden !important;
  transform: none !important;
  clip-path: none !important;
  -webkit-mask: none !important;
  mask: none !important;
  z-index: 0 !important;
}
.premium-card .card-avatar-container,
.premium-card .card-avatar-container > div[style] {
  position: absolute !important;
  box-sizing: border-box !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: none !important;
  max-height: none !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: inherit !important;
  background: transparent !important;
  overflow: hidden !important;
  transform: none !important;
  clip-path: none !important;
  -webkit-mask: none !important;
  mask: none !important;
}
.premium-card .card-avatar {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  border: 0 !important;
  border-radius: 0 !important;
  object-fit: cover !important;
}
.premium-card .card-content::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  inset: 72% 0 0 !important;
  background: linear-gradient(180deg,transparent,#20172d66) !important;
  z-index: 1 !important;
  pointer-events: none !important;
}

/* 姓名与身份来自真实资料，小姓名牌位于绘制星芒下方。 */
.premium-card .roster-nameplate {
  position: absolute !important;
  box-sizing: border-box !important;
  inset: 89.2% 14% 2.4% !important;
  width: auto !important;
  height: auto !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: none !important;
  max-height: none !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  justify-content: flex-start !important;
  gap: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  color: #f3e5cc !important;
  font-family: var(--pc-font) !important;
  text-align: center !important;
  writing-mode: horizontal-tb !important;
  text-orientation: mixed !important;
  transform: none !important;
  pointer-events: none !important;
  isolation: isolate !important;
  z-index: 3 !important;
}
.premium-card .roster-ribbon {
  position: relative !important;
  box-sizing: border-box !important;
  inset: auto !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  flex: 0 0 78% !important;
  width: 100% !important;
  height: 78% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: 100% !important;
  margin: 0 !important;
  padding: 0 13% !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: var(--pc-drawn-name) center / 100% 100% no-repeat !important;
  box-shadow: none !important;
  color: var(--pc-ink) !important;
  text-align: center !important;
  writing-mode: horizontal-tb !important;
  transform: none !important;
  clip-path: none !important;
}
.premium-card :is(.roster-ribbon-name,.roster-nameplate-role) {
  position: static !important;
  box-sizing: border-box !important;
  inset: auto !important;
  width: 100% !important;
  height: auto !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: 100% !important;
  max-height: none !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  font-family: var(--pc-font) !important;
  text-align: center !important;
  writing-mode: horizontal-tb !important;
  text-orientation: mixed !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  transform: none !important;
}
.premium-card .roster-ribbon-name {
  display: block !important;
  color: var(--pc-ink) !important;
  -webkit-text-fill-color: var(--pc-ink) !important;
  font-weight: 500 !important;
  line-height: 1.15 !important;
  letter-spacing: .04em !important;
  text-shadow: none !important;
}
.character-grid > .premium-card .roster-ribbon-name { font-size: 9px !important; }
.carousel-item > .premium-card .roster-ribbon-name { font-size: 14px !important; }
.premium-card .roster-nameplate-role {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  flex: 0 0 22% !important;
  color: #f1e4ce !important;
  font-size: 7px !important;
  line-height: 1.2 !important;
  letter-spacing: .06em !important;
  text-shadow: 0 1px 2px #21182e !important;
}

/* 移除被绘制素材取代的默认装饰。 */
.premium-card .roster-tarot-frame,
.premium-card .card-trail,
.premium-card .roster-nameplate-ornament,
.premium-card .flip-card-back > img,
.tarot-name-star,
.fab-gold > * { display: none !important; }
.premium-card::before,
.premium-card::after,
.premium-card .flip-card-front::before,
.premium-card .flip-card-front::after,
.premium-card .card-border::before,
.premium-card .card-border::after,
.premium-card .card-content::before,
.premium-card .card-avatar-container::before,
.premium-card .card-avatar-container::after,
.premium-card .roster-nameplate::before,
.premium-card .roster-nameplate::after,
.premium-card .roster-ribbon::before,
.premium-card .roster-ribbon::after,
.premium-card .roster-ribbon-name::before,
.premium-card .roster-ribbon-name::after,
.premium-card .flip-card-back::before,
.premium-card .flip-card-back::after,
.expanded-card .tarot-image-frame::before,
.tarot-actions::before,
.tarot-actions::after,
.tarot-actions > .tarot-act::before,
.tarot-actions > .tarot-act::after,
.fab-popup-text::before,
.fab-popup-text::after,
.fab-gold::before {
  content: none !important;
  display: none !important;
}

/* 静态珍珠加号：保留应用的定位及点击事件。 */
.fab-gold {
  box-sizing: border-box !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: var(--pc-fab-size) !important;
  height: var(--pc-fab-size) !important;
  min-width: 44px !important;
  min-height: 44px !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: var(--pc-drawn-pearl) center / contain no-repeat !important;
  box-shadow: none !important;
  filter: drop-shadow(0 3px 5px #82678838) !important;
  color: transparent !important;
  font-size: 0 !important;
  text-shadow: none !important;
  overflow: visible !important;
  animation: none !important;
  z-index: 1002 !important;
}
.fab-gold::after,
.roster-app-container:has(.fab-popup-text) .fab-gold::after,
div:has(> .fab-gold):has(> div > div > .fab-popup-text) > .fab-gold::after {
  content: "+" !important;
  position: static !important;
  display: block !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  color: #99774b !important;
  font-family: Arial,sans-serif !important;
  font-size: 25px !important;
  font-weight: 300 !important;
  line-height: 1 !important;
  text-shadow: 0 1px 1px #fff !important;
  transform: none !important;
  animation: none !important;
  transition: none !important;
  pointer-events: none !important;
}

/* 四项菜单：使用已提供的外层结构，置于蒙罩上方，保留原扇形动画。 */
div[style]:has(> div[style] > .fab-popup-text):has(> div[style] > .fab-popup-icon) {
  z-index: 1001 !important;
}
.fab-popup-text {
  box-sizing: border-box !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  flex: 0 0 auto !important;
  width: auto !important;
  min-width: 94px !important;
  min-height: 30px !important;
  padding: 4px 13px !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: var(--pc-drawn-name) center / 100% 100% no-repeat !important;
  color: #63516b !important;
  font-size: 11.5px !important;
  line-height: 1.35 !important;
  text-shadow: none !important;
  box-shadow: none !important;
}

/* 塔罗详情：头像、姓名牌、资料分区。 */
.expanded-card {
  position: relative !important;
  box-sizing: border-box !important;
  display: flex !important;
  flex-direction: column !important;
  width: min(92vw,460px) !important;
  max-width: calc(100vw - 24px) !important;
  max-height: 78vh !important;
  padding: 0 !important;
  border: 1px solid #c5a06c !important;
  border-radius: 22px !important;
  background: linear-gradient(145deg,#fffcf5,#f7f0ee 48%,#ebe2f1) !important;
  box-shadow: inset 0 0 0 3px #fff9ead1,0 12px 35px #24162f33 !important;
  color: var(--pc-ink) !important;
  font-family: var(--pc-font) !important;
  overflow: hidden !important;
}
.expanded-inner-border {
  position: relative !important;
  box-sizing: border-box !important;
  display: block !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 28px 18px 22px !important;
  border: 0 !important;
  background: transparent !important;
  color: var(--pc-ink) !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
  -webkit-overflow-scrolling: touch !important;
}
.tarot-header {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  gap: 12px !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  text-align: center !important;
}
.tarot-arcana-text {
  color: #a27c4d !important;
  font-family: Georgia,var(--pc-font) !important;
  font-size: 10px !important;
  line-height: 1.4 !important;
  letter-spacing: .16em !important;
  text-shadow: none !important;
}
.expanded-card .tarot-image-frame {
  position: relative !important;
  box-sizing: border-box !important;
  width: min(58%,176px) !important;
  height: auto !important;
  aspect-ratio: 4 / 7 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 4% / 2.2857% !important;
  background: transparent !important;
  box-shadow: none !important;
  filter: drop-shadow(0 3px 6px #4b315529) !important;
  overflow: hidden !important;
  isolation: isolate !important;
  transform: none !important;
}
.expanded-card .tarot-image-frame::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  inset: 0 !important;
  background: var(--pc-drawn-front) center / 100% 100% no-repeat !important;
  z-index: 2 !important;
  pointer-events: none !important;
}
.expanded-card .tarot-image-inner {
  position: absolute !important;
  box-sizing: border-box !important;
  inset: 1.5% 2.625% 3.3% !important;
  width: auto !important;
  height: auto !important;
  padding: 0 !important;
  margin: 0 !important;
  border: 0 !important;
  border-radius: 2.5% / 1.4286% !important;
  background: #efe7ee !important;
  box-shadow: none !important;
  overflow: hidden !important;
  transform: none !important;
  z-index: 0 !important;
}
.tarot-image-inner > div[style] {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  border-radius: inherit !important;
  overflow: hidden !important;
  transform: none !important;
}
.tarot-image-inner .msg-image-img {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  border: 0 !important;
  border-radius: 0 !important;
  object-fit: cover !important;
}
.expanded-card .tarot-name-banner {
  position: relative !important;
  box-sizing: border-box !important;
  inset: auto !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 10px !important;
  width: min(80%,250px) !important;
  min-width: 0 !important;
  min-height: 0 !important;
  height: auto !important;
  aspect-ratio: 800 / 164 !important;
  margin: 0 !important;
  padding: 0 14% !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: var(--pc-drawn-name) center / contain no-repeat !important;
  box-shadow: none !important;
  color: var(--pc-ink) !important;
  transform: none !important;
  clip-path: none !important;
}
.expanded-card .tarot-name-text {
  flex: 0 1 auto !important;
  min-width: 0 !important;
  color: var(--pc-ink) !important;
  font-family: var(--pc-font) !important;
  font-size: 17px !important;
  font-weight: 500 !important;
  line-height: 1.35 !important;
  letter-spacing: .06em !important;
  text-shadow: none !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
.tarot-body {
  display: grid !important;
  gap: 14px !important;
  box-sizing: border-box !important;
  margin: 0 !important;
  padding: 20px 0 0 !important;
  border: 0 !important;
  background: transparent !important;
  color: var(--pc-ink) !important;
  overflow: visible !important;
}
.expanded-section {
  box-sizing: border-box !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 15px 14px !important;
  border: 1px solid #dac6a6 !important;
  border-radius: 13px !important;
  background: linear-gradient(140deg,#fffaf4eb,#eee4f1ad) !important;
  color: var(--pc-ink) !important;
}
.expanded-label {
  margin: 0 0 12px !important;
  padding: 0 0 9px !important;
  border: 0 !important;
  border-bottom: 1px solid #e3d1b4 !important;
  background: transparent !important;
  color: #a37c49 !important;
  font-family: var(--pc-font) !important;
  font-size: 12px !important;
  line-height: 1.4 !important;
  letter-spacing: .09em !important;
  text-align: left !important;
}
.expanded-section > .expanded-label + div:not(.expanded-value) {
  color: var(--pc-ink) !important;
  font-family: var(--pc-font) !important;
  font-size: 17px !important;
  font-weight: 500 !important;
  line-height: 1.6 !important;
  letter-spacing: .05em !important;
  margin-bottom: 12px !important;
  text-align: center !important;
}
.tag-gold {
  display: inline-block !important;
  padding: 4px 10px !important;
  border: 1px solid #cbb4d9 !important;
  border-radius: 999px !important;
  background: linear-gradient(135deg,#fbf7fe,#e7ddee) !important;
  color: #675476 !important;
  font-family: var(--pc-font) !important;
  font-size: 11px !important;
  line-height: 1.4 !important;
  letter-spacing: .03em !important;
}
.expanded-value {
  margin: 0 !important;
  padding: 0 !important;
  color: var(--pc-ink-2) !important;
  font-family: var(--pc-font) !important;
  font-size: 13.5px !important;
  line-height: 1.85 !important;
  letter-spacing: .025em !important;
  white-space: pre-wrap !important;
  word-break: break-word !important;
  overflow-wrap: anywhere !important;
  text-align: left !important;
  text-align-last: auto !important;
}

/* 详情操作：六颗珍珠直接排列，保留原 SVG 图标。 */
.roster-detail-style-btn {
  position: absolute !important;
  inset: 12px 12px auto auto !important;
  box-sizing: border-box !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 44px !important;
  height: 44px !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: var(--pc-drawn-pearl) center / contain no-repeat !important;
  color: #93764f !important;
  box-shadow: none !important;
  z-index: 5 !important;
}
.fab-popup-icon,
.tarot-actions > .tarot-act {
  box-sizing: border-box !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  flex: 0 0 44px !important;
  width: 44px !important;
  height: 44px !important;
  min-width: 44px !important;
  min-height: 44px !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: var(--pc-drawn-pearl) center / contain no-repeat !important;
  color: #8d704d !important;
  box-shadow: none !important;
  cursor: pointer !important;
}
.fab-popup-icon > svg,
.tarot-actions > .tarot-act > svg {
  display: block !important;
  width: 18px !important;
  height: 18px !important;
  fill: none !important;
  stroke: currentColor !important;
  pointer-events: none !important;
}
.fab-popup-icon > svg *,
.tarot-actions > .tarot-act > svg * { stroke: currentColor !important; }
.tarot-actions {
  box-sizing: border-box !important;
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  flex-shrink: 0 !important;
  flex-wrap: nowrap !important;
  width: min(410px,calc(100vw - 36px)) !important;
  max-width: calc(100vw - 36px) !important;
  gap: clamp(3px,1.1vw,6px) !important;
  margin: 10px auto 0 !important;
  padding: 8px 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  outline: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
.tarot-actions > .tarot-act.is-warn { color: #a47a44 !important; }
.tarot-actions > .tarot-act.is-danger { color: #b16679 !important; }
.tarot-actions > .tarot-act.is-close { color: #75617f !important; }
.fab-popup-icon:active,
.tarot-actions > .tarot-act:active { filter: brightness(.94) !important; }
@media (max-width: 340px) {
  .tarot-actions { gap: 2px !important; }
  .tarot-actions > .tarot-act {
    flex-basis: 42px !important;
    width: 42px !important;
    min-width: 42px !important;
  }
}

/* 浅色资料面板：使用已确认的容器、表单元素和行内白色。 */
.expanded-card :is(p,small),
.expanded-card :is(div,span,p,small,label)[style*="color: white" i],
.expanded-card :is(div,span,p,small,label)[style*="color:white" i],
.expanded-card :is(div,span,p,small,label)[style*="color: #fff" i],
.expanded-card :is(div,span,p,small,label)[style*="color:#fff" i],
.expanded-card :is(div,span,p,small,label)[style*="color: rgb(255, 255, 255)"],
.expanded-card :is(div,span,p,small,label)[style*="color: rgba(255, 255, 255,"],
.expanded-card :is(div,span,p,small,label)[style*="color:rgb(255,255,255)"],
.expanded-card :is(div,span,p,small,label)[style*="color:rgba(255,255,255,"] {
  color: #63536e !important;
  -webkit-text-fill-color: #63536e !important;
  text-shadow: none !important;
}
.expanded-card :is(input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="file"]):not([type="color"]):not([type="button"]):not([type="submit"]),textarea,select) {
  box-sizing: border-box !important;
  color: #3e304b !important;
  -webkit-text-fill-color: #3e304b !important;
  background: #fffaf7 !important;
  border: 1px solid #cdb8d6 !important;
  box-shadow: inset 0 1px 3px #60496b0a !important;
  caret-color: #91729f !important;
}
.expanded-card :is(input,textarea)::placeholder {
  color: #7d6d88 !important;
  -webkit-text-fill-color: #7d6d88 !important;
  opacity: 1 !important;
}
.expanded-card input[type="range"] { background: transparent !important; accent-color: #b498c8 !important; }
.expanded-card input[type="range"]::-webkit-slider-runnable-track {
  height: 6px !important;
  border-radius: 999px !important;
  background: #d9c9e5 !important;
}
.expanded-card input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none !important;
  width: 18px !important;
  height: 18px !important;
  margin-top: -6px !important;
  border: 1px solid #b798cc !important;
  border-radius: 50% !important;
  background: #fffaf7 !important;
}

/* 名牌微调：仅修底部卡面姓名牌，不影响菜单小名牌。 */
.premium-card .roster-nameplate {
  inset: 88.7% 14% 2.9% !important;
}
.premium-card .roster-ribbon {
  flex: 0 0 auto !important;
  width: min(100%, 100%) !important;
  height: auto !important;
  aspect-ratio: 800 / 164 !important;
  align-self: center !important;
  padding: 0 14% !important;
  background: var(--pc-drawn-name) center / contain no-repeat !important;
}
.premium-card .roster-ribbon-name {
  position: relative !important;
  top: -1px !important;
  line-height: 1.05 !important;
}
.character-grid > .premium-card .roster-ribbon-name {
  font-size: 8.8px !important;
}
.carousel-item > .premium-card .roster-ribbon-name {
  font-size: 13.5px !important;
}

value.css:
/*⁣​‌‌‍‍​⁠‌‌​​‍⁠⁠‍​‌​​⁠‌‌‍​​‍‍‌​​​‍⁠‌⁠​⁠‌⁠‍‌‍‍‌‌⁠⁠⁠‍‍‍⁠​⁠‌‌‍⁠⁠‌‍‍‌​⁣
  此时此刻 · 夏日庭院 v5 透景书角与玻璃外框
  适用：经典主题 → 设定 → 画面美化 → 自定义 CSS → 添加/导入。
  你的消息是独立素色小框，角色的消息是独立的半透明阅读卡。
  开启 App 自带的「翻页模式」后，输入区上方显示真实翻页栏。
  CSS 不会打开翻页开关，也不会把多条消息强行合并或删掉。
  背景已经内嵌，不用另填图床；文件控制在教程的 100KB 上限内。
  名字、剧情、页码继续读取 App 数据，不写死人物或故事正文。
  底部是原有功能按钮的编号样式，不是游戏的固定六章目录。
  改章节装饰标题：只修改下面 --ct-chapter-title 的引号内文字。
  可调正文大小：--ct-body-size；留边：--ct-side / --ct-inner。
*/

:root {
  --ct-chapter-title: "夏日来信";
  --ct-ink: #55514f;
  --ct-muted: #99918c;
  --ct-accent: #b77c6b;
  --ct-body-size: 15px;
  --ct-body-leading: 1.95;
  --ct-side: 22px;
  --ct-inner: 35px;
  --ct-heading-offset: 22px;
  --ct-char-min-height: clamp(300px, 56dvh, 510px);
  --ct-safe-top: var(--nuo-safe-top, 54px);
  --ct-safe-bottom: var(--nuo-safe-bottom, 20px);
  --ct-background: url("data:image/webp;base64,");
  --tm-text-area-top: 0px;
  --tm-text-area-right: 0px;
  --tm-text-area-bottom: 0px;
  --tm-text-area-left: 0px;
  --tm-text-area-rotate: 0deg;
  --tm-fg: #55514f;
  --tm-fg-muted: #918783;
  --tm-bg-soft: #f3eeea;
  --tm-border: rgba(153, 129, 116, .22);
}

/* 背景与少量流线；装饰不拦截点击。 */
.tm-bg-container {
  overflow: hidden !important;
  pointer-events: none !important;
}
.tm-bg-image {
  opacity: 0 !important;
}
.tm-bg-overlay {
  position: absolute !important;
  inset: 0 !important;
  opacity: 1 !important;
  background-color: #858e78 !important;
  background-image: linear-gradient(180deg, rgba(22, 31, 20, .04), rgba(52, 43, 40, .06)), var(--ct-background) !important;
  background-position: center center !important;
  background-repeat: no-repeat !important;
  background-size: cover !important;
  filter: none !important;
}
.tc-deco-top, .tc-deco-left, .tc-deco-center, .tc-watermark {
  display: none !important;
}
.tc-deco-right {
  display: block !important;
  position: absolute !important;
  top: -7% !important;
  right: -23% !important;
  width: 52% !important;
  height: 86% !important;
  border-left: 1px solid rgba(255, 255, 255, .2) !important;
  border-radius: 45% !important;
  box-shadow: -5px 0 0 rgba(255,255,255,.1), -10px 0 0 rgba(255,255,255,.09), -15px 0 0 rgba(255,255,255,.075), -20px 0 0 rgba(255,255,255,.06) !important;
  transform: rotate(-21deg) !important;
  pointer-events: none !important;
}
.tc-deco-bottom {
  display: block !important;
  position: absolute !important;
  bottom: -16% !important;
  left: -15% !important;
  width: 120% !important;
  height: 24% !important;
  border-top: 1px solid rgba(255,255,255,.18) !important;
  border-radius: 50% !important;
  box-shadow: 0 -5px 0 rgba(255,255,255,.09), 0 -10px 0 rgba(255,255,255,.07), 0 -15px 0 rgba(255,255,255,.05) !important;
  transform: rotate(12deg) !important;
  pointer-events: none !important;
}

/* 顶栏：沿用返回、角色/面具切换、分页和设定按钮。 */
.tm-header {
  position: relative !important;
  z-index: 2 !important;
  display: grid !important;
  grid-template-columns: 34px minmax(0, 1fr) auto !important;
  align-items: center !important;
  column-gap: 7px !important;
  flex: 0 0 auto !important;
