.tm-regen-btn:is([title^="照下"], [title^="拍照"], [title^="Take"], [title^="Snapshot"]) { --ct-tool-number: "5"; --ct-tool-label: "拍照"; }
.tm-regen-btn:is([title^="完结"], [title^="完結"], [title^="Finish"]) { --ct-tool-number: "6"; --ct-tool-label: "完结"; }
.tm-suggestions-btn { --ct-tool-number: "7"; --ct-tool-label: "回应"; }
.tm-regen-btn.active, .tm-suggestions-btn.active, .tm-regen-btn:active, .tm-suggestions-btn:active {
  background: linear-gradient(160deg, rgba(245,227,209,.55), rgba(230,164,136,.86)) !important;
  border-color: #fff !important;
  box-shadow: 0 8px 17px rgba(239,174,142,.38) !important;
}
.tm-regen-btn:disabled, .tm-suggestions-btn:disabled { opacity: .44 !important; }

/* 输入区保持可用，不让小字号触发 iOS 自动放大。 */
.tm-compose-row {
  position: static !important;
  display: flex !important;
  align-items: flex-end !important;
  gap: 8px !important;
  margin: 11px 0 0 !important;
  padding: 0 !important;
  border: none !important;
  background: transparent !important;
}
.tm-input {
  box-sizing: border-box !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  min-height: 40px !important;
  max-height: 110px !important;
  margin: 0 !important;
  padding: 8px 12px !important;
  border: 1px solid rgba(255,255,255,.7) !important;
  border-radius: 20px !important;
  background: rgba(255,255,255,.68) !important;
  box-shadow: inset 0 1px 2px rgba(255,255,255,.27) !important;
  color: #5c514c !important;
  font-family: -apple-system, "PingFang SC", sans-serif !important;
  font-size: 16px !important;
  line-height: 22px !important;
  caret-color: #b5806b !important;
  resize: none !important;
}
.tm-input::placeholder { color: #a59387 !important; font-size: 13px !important; }
.tm-send-btn {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  box-sizing: border-box !important;
  flex: 0 0 39px !important;
  width: 39px !important;
  height: 39px !important;
  margin: 0 !important;
  padding: 10px !important;
  border: 1px solid rgba(255,255,255,.75) !important;
  border-radius: 50% !important;
  background: rgba(255,255,255,.64) !important;
  color: #ad806b !important;
  box-shadow: none !important;
  -webkit-tap-highlight-color: transparent !important;
}
.tm-send-btn.ready { background: #e8cdb9 !important; color: #fff !important; }
.tm-send-btn.tm-stop-btn { background: #bd8d7b !important; color: #fff !important; }
.tm-send-btn:disabled { opacity: .5 !important; }

/* 建议、章节抽屉和辅助面板使用同一套浅纸色，不隐藏功能。 */
.tm-suggestions-panel, .tm-context-menu, .tm-session-browser {
  color: #65584f !important;
  background: rgba(250,247,240,.97) !important;
  border: 1px solid rgba(255,255,255,.92) !important;
  box-shadow: 0 8px 30px rgba(49,42,32,.18) !important;
}
.tm-suggestions-panel {
  max-height: min(32dvh, 240px) !important;
  margin: 0 0 12px !important;
  padding: 10px !important;
  border-radius: 15px !important;
  overflow-y: auto !important;
  -webkit-overflow-scrolling: touch !important;
}
.tm-suggestion-item { background: #fffdf8 !important; border: 1px solid #e9ded3 !important; border-radius: 9px !important; }
.tm-suggestion-direction, .tm-suggestion-reroll { color: #b38871 !important; }
.tm-suggestion-text { color: #6c5c51 !important; font-size: 13px !important; line-height: 1.8 !important; }
.tm-suggestion-error, .tm-ctx-delete { color: #b87367 !important; }
.tm-suggestion-dot, .tm-skeleton { background: #dfcbbb !important; }
.tm-session-browser { width: min(88vw, 350px) !important; }
.tm-session-browser-header { border-color: #e5d7ca !important; background: #f8f3ed !important; }
.tm-session-browser-title { color: #756153 !important; font-family: "Songti SC", "STSong", serif !important; font-size: 18px !important; }
.tm-session-list { display: grid !important; grid-template-columns: repeat(2, minmax(0, 1fr)) !important; align-content: start !important; gap: 10px !important; padding: 14px !important; counter-reset: ct-session; }
.tm-session-item { position: relative !important; min-width: 0 !important; padding: 12px !important; background: #fffdf8 !important; border: 1px solid #e6d5c5 !important; border-radius: 2px 18px 2px 2px !important; counter-increment: ct-session; }
.tm-session-item::before { content: counter(ct-session, decimal-leading-zero) !important; display: block !important; color: #bc9580 !important; font-family: Georgia, serif !important; font-size: 21px !important; line-height: 1.5 !important; }
.tm-session-item.active, .tm-session-item.merge-selected { background: #f2e4d7 !important; border-color: #c59b7e !important; }
.tm-session-item-name { color: #76614f !important; font-size: 12px !important; }
.tm-session-item-meta { color: #ad9b8b !important; font-size: 9px !important; }
.tm-session-new-btn { color: #a58269 !important; border-color: #d7bea8 !important; background: #faf5ed !important; border-radius: 2px !important; }
.tm-context-menu button { color: #7c695b !important; }
.tm-history-bar, .tm-multiselect-bar { color: #786353 !important; background: #f8f3eb !important; border-color: #e7d5c4 !important; }
.tm-greeting-swiper, .tm-time-jump-pill { color: #a88670 !important; background: #f4e9df !important; border-color: #dac3ad !important; }
.tm-time-jump-line { background: #d1b499 !important; }
.tm-jump-nav { right: 2px !important; gap: 5px !important; background: transparent !important; }
.tm-jump-btn { width: 23px !important; height: 23px !important; padding: 4px !important; border-radius: 50% !important; color: #a88670 !important; background: rgba(255,251,245,.85) !important; border: 1px solid rgba(196,164,135,.3) !important; }
.tm-loading-text, .tm-story-empty { color: #a38d7c !important; font-size: 12px !important; }
.tm-cast-change-notice, .tm-cast-suggestion, .tm-solo-upgrade-suggestion { background: #faf4ec !important; color: var(--tm-fg) !important; border: 1px solid var(--tm-border) !important; border-radius: 9px !important; }
.tm-mode-seg-btn { --tm-fg: #a08d7f; }
.tm-mode-seg-btn.active { --tm-bg: #f5e8db; --tm-fg: #8a6a54; }
.tm-para.tm-selected { outline: 1px solid #c99f7f !important; outline-offset: 5px !important; }
.tm-select-checkbox { accent-color: #bf9375; }
.tm-btn-icon:focus-visible, .tm-regen-btn:focus-visible, .tm-suggestions-btn:focus-visible, .tm-send-btn:focus-visible, .tm-page-btn:focus-visible {
  outline: 2px solid #edc6a5 !important;
  outline-offset: 3px !important;
}

@media (max-width: 360px) {
  :root { --ct-side: 16px; --ct-inner: 26px; --ct-body-size: 14px; }
  .tm-story { padding-top: 12px !important; }
  .tm-story .tm-para-char { padding-top: 30px !important; border-top-right-radius: 70px !important; }
  .tc-meta-subtitle::before { font-size: 20px !important; }
  .tm-compose-toolbar { gap: 6px !important; padding-left: 3px !important; padding-right: 3px !important; }
  .tm-regen-btn, .tm-suggestions-btn { flex-basis: 28px !important; width: 28px !important; min-width: 28px !important; }
}
