    linear-gradient(180deg, rgba(255,255,255,0) 0px, rgba(255,255,255,.12) 65px, rgba(255,255,255,.94) 150px, #fff 210px),
    linear-gradient(90deg, rgba(255,255,255,.98) 0%, rgba(255,255,255,.88) 38%, rgba(255,255,255,.34) 76%, rgba(255,255,255,.1) 100%),
    linear-gradient(rgba(255,255,255,.17), rgba(255,255,255,.17)) !important;
