.tm-regen-btn:is([title^="照下"], [title^="拍照"], [title^="Take"], [title^="Snapshot"]) { --ct-tool-number: "5"; --ct-tool-label: "拍照"; }
.tm-regen-btn:is([title^="完结"], [title^="完結"], [title^="Finish"]) { --ct-tool-number: "6"; --ct-tool-label: "完结"; }
.tm-suggestions-btn { --ct-tool-number: "7"; --ct-tool-label: "回应"; }
.tm-regen-btn.active, .tm-suggestions-btn.active, .tm-regen-btn:active, .tm-suggestions-btn:active {
