/*⁣​‌‌‍‍​⁠‌‌​​‍⁠⁠‍​‌​​⁠‌‌‍​​‍‍‌​​​‍⁠‌⁠​⁠‌⁠‍‌‍‍‌‌⁠⁠⁠‍‍‍⁠​⁠‌‌‍⁠⁠‌‍‍‌​⁣
  此时此刻 · 夏日庭院 v5 透景书角与玻璃外框
  适用：经典主题 → 设定 → 画面美化 → 自定义 CSS → 添加/导入。
  你的消息是独立素色小框，角色的消息是独立的半透明阅读卡。
  开启 App 自带的「翻页模式」后，输入区上方显示真实翻页栏。
  CSS 不会打开翻页开关，也不会把多条消息强行合并或删掉。
  背景已经内嵌，不用另填图床；文件控制在教程的 100KB 上限内。
  名字、剧情、页码继续读取 App 数据，不写死人物或故事正文。
  底部是原有功能按钮的编号样式，不是游戏的固定六章目录。
  改章节装饰标题：只修改下面 --ct-chapter-title 的引号内文字。
  可调正文大小：--ct-body-size；留边：--ct-side / --ct-inner。
*/

:root {
  --ct-chapter-title: "夏日来信";
  --ct-ink: #55514f;
  --ct-muted: #99918c;
  --ct-accent: #b77c6b;
  --ct-body-size: 15px;
  --ct-body-leading: 1.95;
  --ct-side: 22px;
  --ct-inner: 35px;
  --ct-heading-offset: 22px;
  --ct-char-min-height: clamp(300px, 56dvh, 510px);
  --ct-safe-top: var(--nuo-safe-top, 54px);
  --ct-safe-bottom: var(--nuo-safe-bottom, 20px);
  --ct-background: url("data:image/webp;base64,");
  --tm-text-area-top: 0px;
  --tm-text-area-right: 0px;
  --tm-text-area-bottom: 0px;
  --tm-text-area-left: 0px;
  --tm-text-area-rotate: 0deg;
  --tm-fg: #55514f;
  --tm-fg-muted: #918783;
  --tm-bg-soft: #f3eeea;
  --tm-border: rgba(153, 129, 116, .22);
}

/* 背景与少量流线；装饰不拦截点击。 */
.tm-bg-container {
  overflow: hidden !important;
  pointer-events: none !important;
}
.tm-bg-image {
  opacity: 0 !important;
}
.tm-bg-overlay {
  position: absolute !important;
  inset: 0 !important;
  opacity: 1 !important;
  background-color: #858e78 !important;
  background-image: linear-gradient(180deg, rgba(22, 31, 20, .04), rgba(52, 43, 40, .06)), var(--ct-background) !important;
  background-position: center center !important;
  background-repeat: no-repeat !important;
  background-size: cover !important;
  filter: none !important;
}
.tc-deco-top, .tc-deco-left, .tc-deco-center, .tc-watermark {
  display: none !important;
}
.tc-deco-right {
  display: block !important;
  position: absolute !important;
  top: -7% !important;
  right: -23% !important;
  width: 52% !important;
  height: 86% !important;
  border-left: 1px solid rgba(255, 255, 255, .2) !important;
  border-radius: 45% !important;
  box-shadow: -5px 0 0 rgba(255,255,255,.1), -10px 0 0 rgba(255,255,255,.09), -15px 0 0 rgba(255,255,255,.075), -20px 0 0 rgba(255,255,255,.06) !important;
  transform: rotate(-21deg) !important;
  pointer-events: none !important;
}
.tc-deco-bottom {
  display: block !important;
  position: absolute !important;
  bottom: -16% !important;
  left: -15% !important;
  width: 120% !important;
  height: 24% !important;
  border-top: 1px solid rgba(255,255,255,.18) !important;
  border-radius: 50% !important;
  box-shadow: 0 -5px 0 rgba(255,255,255,.09), 0 -10px 0 rgba(255,255,255,.07), 0 -15px 0 rgba(255,255,255,.05) !important;
  transform: rotate(12deg) !important;
  pointer-events: none !important;
}

/* 顶栏：沿用返回、角色/面具切换、分页和设定按钮。 */
.tm-header {
  position: relative !important;
  z-index: 2 !important;
  display: grid !important;
  grid-template-columns: 34px minmax(0, 1fr) auto !important;
  align-items: center !important;
  column-gap: 7px !important;
  flex: 0 0 auto !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: calc(var(--ct-safe-top) + 8px) 16px 13px !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
.tm-header > .tm-btn-icon:first-child {
  grid-column: 1 !important;
  width: 34px !important;
  height: 34px !important;
  background-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2028%2034%22%3E%3Cpath%20d%3D%22M20%204L10%2014l4%204%2010-10Z%22%20fill%3D%22white%22%2F%3E%3Cpath%20d%3D%22M10%2020l10%2010h4L14%2020Z%22%20fill%3D%22white%22%2F%3E%3Cpath%20d%3D%22M7%2015l3%203-3%203-3-3Z%22%20fill%3D%22white%22%2F%3E%3C%2Fsvg%3E") !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: 21px 25px !important;
  border: none !important;
  border-radius: 0 !important;
  filter: drop-shadow(0 1px 2px rgba(0,0,0,.2)) !important;
}
.tm-header > .tm-btn-icon:first-child > * {
  visibility: hidden !important;
}
.tm-header-center {
  grid-column: 2 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 4px !important;
  min-width: 0 !important;
  overflow: hidden !important;
  background: none !important;
}
.tm-header-avatar, .tm-header-avatar-wrap, .tm-header-avatar-fallback {
  display: none !important;
}
.tm-top-drop-btn, .tm-top-drop-btn-user {
  min-width: 0 !important;
  max-width: 44% !important;
  margin: 0 !important;
  padding: 3px 1px !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
}
.tm-header-name {
  display: block !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
  font-size: 10px !important;
  font-weight: 400 !important;
  letter-spacing: .5px !important;
  color: rgba(255,255,255,.86) !important;
  text-shadow: 0 1px 3px rgba(23,37,20,.45) !important;
}
.tm-top-vs {
  color: rgba(255,255,255,.55) !important;
  font-size: 10px !important;
}
.tm-header-right {
  grid-column: 3 !important;
  display: flex !important;
  align-items: center !important;
  gap: 7px !important;
}
.tm-header-right .tm-btn-icon {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  flex: 0 0 29px !important;
  width: 29px !important;
  height: 29px !important;
  min-width: 29px !important;
  padding: 6px !important;
  border: 1px solid rgba(255,255,255,.5) !important;
  border-radius: 50% !important;
  background: rgba(234,232,220,.13) !important;
  color: #fff !important;
  box-shadow: 0 1px 5px rgba(28,34,21,.08) !important;
}
.tm-header-right .tm-btn-icon svg {
  width: 17px !important;
  height: 17px !important;
  stroke-width: 1.35 !important;
}

/* 故事区只负责滚动，纸面分别画在每条消息上。 */
.tm-story {
  position: relative !important;
  z-index: 1 !important;
  box-sizing: border-box !important;
  flex: 1 1 auto !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 16px var(--ct-side) 18px !important;
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
  -webkit-overflow-scrolling: touch !important;
  overscroll-behavior-y: contain;
  scrollbar-width: thin;
  scrollbar-color: rgba(156,134,119,.23) transparent;
}
.tm-story::-webkit-scrollbar { width: 3px !important; }
.tm-story::-webkit-scrollbar-track { background: transparent !important; }
.tm-story::-webkit-scrollbar-thumb { background: rgba(156,134,119,.23) !important; border-radius: 3px !important; }
.tm-load-more {
  display: block !important;
  width: fit-content !important;
  margin: 0 auto 20px !important;
  padding: 4px 12px !important;
  border: 1px solid rgba(176,149,131,.2) !important;
  border-radius: 16px !important;
  color: #9f8c80 !important;
  background: rgba(255,255,255,.24) !important;
  font-size: 10px !important;
}
.tm-para {
  position: relative !important;
  margin: 0 0 25px !important;
  padding: 0 !important;
  rotate: 0deg !important;
  transform: none !important;
}
.tm-para-char, .tm-para-user {
  position: relative !important;
  display: block !important;
  box-sizing: border-box !important;
  width: 100% !important;
  max-width: none !important;
  min-height: 0 !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  overflow: visible !important;
  -webkit-tap-highlight-color: transparent !important;
}
.tm-para-user {
  padding: 14px 17px !important;
}
/* 角色：顶部少量透景；155px 后接近白纸，210px 后全白。
   使用固定高度的渐变，长回复不会把透明区拉进正文。 */
.tm-story .tm-para-char {
  min-height: var(--ct-char-min-height) !important;
  padding: 38px var(--ct-inner) 30px !important;
  background:
    linear-gradient(180deg, rgba(255,255,255,0) 0px, rgba(255,255,255,.12) 65px, rgba(255,255,255,.94) 150px, #fff 210px),
    linear-gradient(90deg, rgba(255,255,255,.98) 0%, rgba(255,255,255,.88) 38%, rgba(255,255,255,.34) 76%, rgba(255,255,255,.1) 100%),
    linear-gradient(rgba(255,255,255,.17), rgba(255,255,255,.17)) !important;
  background-clip: padding-box, padding-box, border-box !important;
  background-origin: padding-box, padding-box, border-box !important;
  border: 5px solid transparent !important;
  border-radius: 0 88px 0 0 !important;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.92), inset 0 0 0 5px rgba(255,255,255,.06), 0 6px 20px rgba(27,31,23,.1) !important;
  backdrop-filter: blur(1.5px) !important;
  -webkit-backdrop-filter: blur(1.5px) !important;
}
/* 用户：每条回复各有一张朴素小框，不套章节装饰。 */
.tm-story .tm-para-user {
  width: fit-content !important;
  min-width: min(150px, 100%) !important;
  max-width: 92% !important;
  min-height: 0 !important;
  margin: 0 0 0 auto !important;
  padding: 14px 17px !important;
  background: rgba(255,254,249,.88) !important;
  border: 1px solid rgba(235,226,211,.8) !important;
  border-radius: 4px !important;
  box-shadow: 0 2px 6px rgba(42,39,29,.035) !important;
}
/* 清理旧主题的报头、背景标签；备注和正文仍使用真实内容。 */
.tm-para::before, .tm-para::after,
.tm-para-char::before, .tm-para-char::after,
.tm-para-user::before, .tm-para-user::after,
.tc-header-main::before, .tc-header-main::after,
.tc-meta-title::before, .tc-meta-title::after,
.tc-meta-subtitle::after, .tc-divider-text::after,
.tc-header:not(.tc-header-user)::after,
.tc-header-user::before, .tc-header-user::after,
.tc-meta-title-user::before, .tc-meta-title-user::after {
  content: none !important;
  display: none !important;
}

/* 章节头：真实人物备注 + 真实段落编号 + 可修改的装饰标题。 */
.tc-header:not(.tc-header-user) {
  display: block !important;
  position: relative !important;
  margin: var(--ct-heading-offset) 0 9px !important;
  padding: 14px 0 10px !important;
  background: transparent !important;
  border: none !important;
}
.tc-header:not(.tc-header-user)::before {
  content: "Story" !important;
  position: absolute !important;
  left: -14px !important;
  top: -2px !important;
  z-index: 0 !important;
  color: rgba(159,150,172,.35) !important;
  font-family: "Snell Roundhand", "Brush Script MT", "Apple Chancery", cursive !important;
  font-size: 54px !important;
  font-weight: 400 !important;
  font-style: italic !important;
  line-height: 1 !important;
  letter-spacing: -2px !important;
  transform: rotate(-9deg) !important;
  pointer-events: none !important;
}
.tc-header-main {
  position: relative !important;
  z-index: 1 !important;
  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
}
.tc-header .tc-avatar-area, .tc-header-deco, .tc-header-deco-user {
  display: none !important;
}
.tc-meta-area {
  display: grid !important;
  grid-template-columns: max-content minmax(0, 1fr) !important;
  grid-template-rows: auto auto !important;
  align-items: center !important;
  column-gap: 10px !important;
  row-gap: 5px !important;
  width: 100% !important;
  min-width: 0 !important;
}
.tc-meta-title {
  grid-column: 1 / -1 !important;
  grid-row: 1 !important;
  max-width: 100% !important;
  margin: 0 !important;
  color: #9c9391 !important;
  font-size: 10px !important;
  line-height: 1.4 !important;
  font-weight: 400 !important;
  letter-spacing: 2px !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}
.tc-meta-stats {
  display: contents !important;
}
.tc-meta-stats .tc-stat:not([data-label="page"]) {
  display: none !important;
}
.tc-meta-stats .tc-stat[data-label="page"] {
  grid-column: 1 !important;
  grid-row: 2 !important;
  display: block !important;
  margin: 0 !important;
  padding: 0 10px 0 0 !important;
  border: none !important;
  border-right: 1px solid #aaa19d !important;
  border-radius: 0 !important;
  background: transparent !important;
  color: var(--ct-accent) !important;
  font-family: Georgia, "Times New Roman", serif !important;
  font-size: 26px !important;
  font-weight: 400 !important;
  line-height: 1 !important;
}
.tc-meta-subtitle {
  grid-column: 2 !important;
  grid-row: 2 !important;
  display: block !important;
  min-width: 0 !important;
  min-height: 27px !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
}
.tc-meta-subtitle::before {
  content: var(--ct-chapter-title) !important;
  display: block !important;
  color: #514d4b !important;
  font-family: "Songti SC", "STSong", "Noto Serif CJK SC", "SimSun", serif !important;
  font-size: 22px !important;
  font-weight: 500 !important;
  line-height: 1.2 !important;
  letter-spacing: 1px !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}
.tc-meta-extra-1, .tc-meta-extra-2 { display: none !important; }
.tc-divider {
  display: block !important;
  position: relative !important;
  margin: 5px 0 0 !important;
  padding: 4px 0 0 !important;
  border: 0 !important;
  border-top: 1px solid rgba(166,155,146,.33) !important;
}
.tc-divider-text {
  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
  min-height: 10px !important;
  font-size: 6px !important;
  line-height: 1.4 !important;
  background: none !important;
}
.tc-divider-text::before {
  content: "+  LOVE AND DEEPSPACE  + +" !important;
  color: rgba(153,138,128,.5) !important;
  font-family: Arial, sans-serif !important;
  font-size: 6px !important;
  line-height: 1.4 !important;
  letter-spacing: 1.9px !important;
}
.tc-header-user {
  display: block !important;
  margin: 0 0 5px !important;
  padding: 0 !important;
  border: none !important;
  background: none !important;
}
.tc-meta-area-user { display: block !important; }
.tc-meta-title-user {
  display: block !important;
  color: #a79186 !important;
  font-size: 9px !important;
  line-height: 1.5 !important;
  font-weight: 400 !important;
  letter-spacing: 1px !important;
}
.tc-meta-subtitle-user, .tc-meta-stats-user, .tc-meta-extra-user, .tc-divider-user {
  display: none !important;
}

/* 正文、对白和动态内容均保留真实文本。 */
.tm-body-char, .tm-body-user {
  position: relative !important;
  width: auto !important;
  min-width: 0 !important;
  max-width: 100% !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  color: var(--ct-ink) !important;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", sans-serif !important;
  font-size: var(--ct-body-size) !important;
  line-height: var(--ct-body-leading) !important;
  letter-spacing: .3px !important;
  text-align: justify !important;
  text-shadow: none !important;
  overflow: visible !important;
  overflow-wrap: anywhere;
  -webkit-font-smoothing: antialiased !important;
}
.tm-body-user {
  color: #887269 !important;
  font-size: calc(var(--ct-body-size) - .5px) !important;
  line-height: 1.8 !important;
  text-align: left !important;
}
.tm-body-char .tm-para-block, .tm-body-user .tm-para-block {
  margin: 0 0 .6em !important;
  padding: 0 !important;
  font-size: inherit !important;
  line-height: inherit !important;
  text-indent: 2em;
  opacity: 1 !important;
  transform: none !important;
}
.tm-body-char .tm-para-block:first-child, .tm-body-user .tm-para-block:first-child {
  text-indent: 0;
}
.tm-body-user .tm-para-block { text-indent: 0 !important; }
.tm-body-char .tm-para-block:last-child, .tm-body-user .tm-para-block:last-child { margin-bottom: 0 !important; }
.tm-bold {
  color: #4e4947 !important;
  background: none !important;
  font-weight: 600 !important;
}
.tm-action { color: inherit !important; background: none !important; }
.tm-del { color: #a99b92 !important; }
.tm-quote-block, .tm-quote, .tm-body-char .tm-quote-block, .tm-body-user .tm-quote-block {
  color: inherit !important;
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
  box-shadow: none !important;
}
.tm-heading {
  font-family: "Songti SC", "STSong", "SimSun", serif !important;
  color: #68564d !important;
  font-size: 1.12em !important;
  line-height: 1.7 !important;
  margin: 1em 0 .5em !important;
}
.tm-stream-cursor { background: var(--ct-accent) !important; }
.tm-thinking-wrapper, .tm-translation-section, .tm-collapsible-section {
  position: relative !important;
  margin-top: 12px !important;
  padding: 9px 0 9px 12px !important;
  border-left: 1px solid rgba(183,124,107,.3) !important;
  background: transparent !important;
}
.tm-thinking-toggle, .tm-translation-toggle, .tm-collapsible-toggle {
