}
.tm-cg-wrapper { padding: 5px !important; border: 1px solid #e4d8cf !important; border-radius: 2px !important; background: #fffdf8 !important; }
.tm-cg-image { max-width: 100% !important; height: auto !important; border-radius: 0 !important; }
.tm-voice-btn, .tm-quote-voice {
