}
.tm-page-btn svg { width: 17px !important; height: 17px !important; color: #b58772 !important; stroke-width: 1.6 !important; }
.tm-page-btn:disabled { opacity: .3 !important; }
.tm-page-indicator {
  min-width: 45px !important;
  margin: 0 !important;
  padding: 4px !important;
  border: none !important;
  background: none !important;
