  min-width: 30px !important;
  height: 38px !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 1px solid rgba(255,255,255,.85) !important;
  border-radius: 0 !important;
  background: linear-gradient(150deg, rgba(210,186,164,.43), rgba(198,176,158,.66)) !important;
  color: transparent !important;
  font-size: 0 !important;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.11), 0 2px 8px rgba(23,26,20,.06) !important;
  overflow: visible !important;
  counter-increment: ct-tool;
  -webkit-tap-highlight-color: transparent !important;
}
.tm-regen-btn > *, .tm-suggestions-btn > * { display: none !important; }
.tm-regen-btn::before, .tm-suggestions-btn::before {
  content: var(--ct-tool-number, counter(ct-tool)) !important;
  display: block !important;
  color: rgba(255,255,255,.96) !important;
  font-family: Georgia, "Times New Roman", serif !important;
