}
.tm-send-btn.ready { background: #e8cdb9 !important; color: #fff !important; }
.tm-send-btn.tm-stop-btn { background: #bd8d7b !important; color: #fff !important; }
.tm-send-btn:disabled { opacity: .5 !important; }

/* 建议、章节抽屉和辅助面板使用同一套浅纸色，不隐藏功能。 */
.tm-suggestions-panel, .tm-context-menu, .tm-session-browser {
