}
.tm-suggestion-item { background: #fffdf8 !important; border: 1px solid #e9ded3 !important; border-radius: 9px !important; }
.tm-suggestion-direction, .tm-suggestion-reroll { color: #b38871 !important; }
.tm-suggestion-text { color: #6c5c51 !important; font-size: 13px !important; line-height: 1.8 !important; }
.tm-suggestion-error, .tm-ctx-delete { color: #b87367 !important; }
.tm-suggestion-dot, .tm-skeleton { background: #dfcbbb !important; }
.tm-session-browser { width: min(88vw, 350px) !important; }
.tm-session-browser-header { border-color: #e5d7ca !important; background: #f8f3ed !important; }
.tm-session-browser-title { color: #756153 !important; font-family: "Songti SC", "STSong", serif !important; font-size: 18px !important; }
.tm-session-list { display: grid !important; grid-template-columns: repeat(2, minmax(0, 1fr)) !important; align-content: start !important; gap: 10px !important; padding: 14px !important; counter-reset: ct-session; }
.tm-session-item { position: relative !important; min-width: 0 !important; padding: 12px !important; background: #fffdf8 !important; border: 1px solid #e6d5c5 !important; border-radius: 2px 18px 2px 2px !important; counter-increment: ct-session; }
.tm-session-item::before { content: counter(ct-session, decimal-leading-zero) !important; display: block !important; color: #bc9580 !important; font-family: Georgia, serif !important; font-size: 21px !important; line-height: 1.5 !important; }
.tm-session-item.active, .tm-session-item.merge-selected { background: #f2e4d7 !important; border-color: #c59b7e !important; }
.tm-session-item-name { color: #76614f !important; font-size: 12px !important; }
.tm-session-item-meta { color: #ad9b8b !important; font-size: 9px !important; }
.tm-session-new-btn { color: #a58269 !important; border-color: #d7bea8 !important; background: #faf5ed !important; border-radius: 2px !important; }
.tm-context-menu button { color: #7c695b !important; }
.tm-history-bar, .tm-multiselect-bar { color: #786353 !important; background: #f8f3eb !important; border-color: #e7d5c4 !important; }
.tm-greeting-swiper, .tm-time-jump-pill { color: #a88670 !important; background: #f4e9df !important; border-color: #dac3ad !important; }
.tm-time-jump-line { background: #d1b499 !important; }
.tm-jump-nav { right: 2px !important; gap: 5px !important; background: transparent !important; }
.tm-jump-btn { width: 23px !important; height: 23px !important; padding: 4px !important; border-radius: 50% !important; color: #a88670 !important; background: rgba(255,251,245,.85) !important; border: 1px solid rgba(196,164,135,.3) !important; }
.tm-loading-text, .tm-story-empty { color: #a38d7c !important; font-size: 12px !important; }
.tm-cast-change-notice, .tm-cast-suggestion, .tm-solo-upgrade-suggestion { background: #faf4ec !important; color: var(--tm-fg) !important; border: 1px solid var(--tm-border) !important; border-radius: 9px !important; }
.tm-mode-seg-btn { --tm-fg: #a08d7f; }
.tm-mode-seg-btn.active { --tm-bg: #f5e8db; --tm-fg: #8a6a54; }
.tm-para.tm-selected { outline: 1px solid #c99f7f !important; outline-offset: 5px !important; }
.tm-select-checkbox { accent-color: #bf9375; }
.tm-btn-icon:focus-visible, .tm-regen-btn:focus-visible, .tm-suggestions-btn:focus-visible, .tm-send-btn:focus-visible, .tm-page-btn:focus-visible {
