}
.wb-book-modal:not(:has(.wb-ctl-edit.editing)) .wb-entry:has(.wb-entry-content:not(.wb-entry-content-collapsed)) .wb-entry-expand-btn {
  position: static !important;
  order: 5;
  align-self: center;
  opacity: 1 !important;
  margin-top: 14px !important;
  padding: 8px 22px !important;
  border-radius: 999px !important;
  background: rgba(118, 118, 128, .12) !important;
  color: #007aff !important;
  font-family: -apple-system, "PingFang SC", sans-serif !important;
  font-size: 14px !important;
  font-weight: 500 !important;
}

/* ---- 7.6 设定页：iOS 设置那种一行一项 ---- */
.wb-settings-info-row {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 12px !important;
  margin: 0 18px !important;
  padding: 14px 0 !important;
  border: 0 !important;
