}

/* ---- 8.2 每个词条 = 一张白色圆角卡，里面一行一项 ---- */
.wb-book-modal:has(.wb-ctl-edit.editing) .wb-entry {
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 14px !important;
  background: #fff !important;
  box-shadow: none !important;
  overflow: hidden !important;
  transform: none !important;
}
.wb-book-modal:has(.wb-ctl-edit.editing) .wb-entry::before,
.wb-book-modal:has(.wb-ctl-edit.editing) .wb-entry::after {
  display: none !important;
}
.wb-book-modal:has(.wb-ctl-edit.editing) .wb-entry > div {
  gap: 0 !important;
}
/* 每一项之间一根细线，从左边留 16px 开始 */
.wb-book-modal:has(.wb-ctl-edit.editing) .wb-entry > div > * {
  position: relative;
  margin: 0 !important;
