.wb-book-modal:has(.wb-ctl-edit.editing) .wb-entry > div > * + *::before {
  content: "";
  position: absolute;
  top: 0;
  left: 16px;
  right: 0;
  height: .5px;
  background: rgba(60, 60, 67, .2);
