  }
  .wb-ctl-delete::after {
    color: #ff453a !important;
  }

  /* ---- 14.8 编辑模式：黑底 + 深灰分组卡 ---- */
  .wb-book-modal:has(.wb-ctl-edit.editing),
  .wb-book-modal:has(.wb-ctl-edit.editing) .wb-right-page {
