    -webkit-text-fill-color: #ebebf5 !important;
  }
  .wb-adv-inline .wb-adv-label {
    color: #fff !important;
    -webkit-text-fill-color: #fff !important;
  }
  .wb-adv-field .wb-entry-input,
  .wb-adv-field .wb-mini-select {
    background-color: #1c1c1e !important;
    color: #fff !important;
  }
  .wb-adv-inline input[type="checkbox"] {
    background:
      radial-gradient(circle, #fff 12.5px, rgba(0, 0, 0, .3) 13px, transparent 14px) 0 0 / 31px 31px no-repeat,
