/* =========================================================
   15. 安卓兼容：顶栏被状态栏遮住
   iOS 外层已避开状态栏；安卓 WebView 铺满全屏、拿不到 safe-area，
   顶栏就顶到状态栏后面。这里只给「非 iOS」补一段状态栏高度，
   用 -webkit-touch-callout（iOS 专属）把苹果排除在外，iOS 完全不变。
   ========================================================= */
@supports not (-webkit-touch-callout: none) {
  /* 词条页 / 编辑页 / 封面页顶部按钮的距离 */
  :root {
    --wbx-top: calc(env(safe-area-inset-top, 0px) + 36px);
  }
  /* 书柜页 / 列表页顶栏整体下移，避开状态栏 */
  .wb-header {
    padding-top: calc(env(safe-area-inset-top, 0px) + 28px) !important;
  }
}

/* =========================================================
   16. 滚动条改色（细、圆、半透明）
   ========================================================= */
.wb-library,
.wb-entries-container,
.wb-entry-textarea,
.wb-expand-textarea,
.wb-shelf-filter-chips,
.wb-catpick-modal,
.wb-new-modal {
  scrollbar-width: thin;
  scrollbar-color: rgba(60, 60, 67, .3) transparent;
}
.wb-library::-webkit-scrollbar,
.wb-entries-container::-webkit-scrollbar,
.wb-entry-textarea::-webkit-scrollbar,
.wb-expand-textarea::-webkit-scrollbar,
.wb-shelf-filter-chips::-webkit-scrollbar,
.wb-catpick-modal::-webkit-scrollbar,
.wb-new-modal::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
.wb-library::-webkit-scrollbar-track,
.wb-entries-container::-webkit-scrollbar-track,
.wb-entry-textarea::-webkit-scrollbar-track,
.wb-expand-textarea::-webkit-scrollbar-track,
.wb-shelf-filter-chips::-webkit-scrollbar-track,
.wb-catpick-modal::-webkit-scrollbar-track,
.wb-new-modal::-webkit-scrollbar-track {
  background: transparent;
}
.wb-library::-webkit-scrollbar-thumb,
.wb-entries-container::-webkit-scrollbar-thumb,
.wb-entry-textarea::-webkit-scrollbar-thumb,
.wb-expand-textarea::-webkit-scrollbar-thumb,
.wb-shelf-filter-chips::-webkit-scrollbar-thumb,
.wb-catpick-modal::-webkit-scrollbar-thumb,
.wb-new-modal::-webkit-scrollbar-thumb {
  background: rgba(60, 60, 67, .3);
  border-radius: 3px;
}
.wb-library::-webkit-scrollbar-thumb:active,
.wb-entries-container::-webkit-scrollbar-thumb:active {
  background: rgba(60, 60, 67, .5);
}

@media (prefers-color-scheme: dark) {
  .wb-library,
  .wb-entries-container,
  .wb-entry-textarea,
  .wb-expand-textarea,
  .wb-shelf-filter-chips,
  .wb-catpick-modal,
  .wb-new-modal {
    scrollbar-color: rgba(235, 235, 245, .3) transparent;
  }
  .wb-library::-webkit-scrollbar-thumb,
  .wb-entries-container::-webkit-scrollbar-thumb,
  .wb-entry-textarea::-webkit-scrollbar-thumb,
  .wb-expand-textarea::-webkit-scrollbar-thumb,
  .wb-shelf-filter-chips::-webkit-scrollbar-thumb,
  .wb-catpick-modal::-webkit-scrollbar-thumb,
  .wb-new-modal::-webkit-scrollbar-thumb {
    background: rgba(235, 235, 245, .3);
  }
  .wb-library::-webkit-scrollbar-thumb:active,
  .wb-entries-container::-webkit-scrollbar-thumb:active {
    background: rgba(235, 235, 245, .5);
  }
}


/* =========================================================
   17. 词条小纸：加一圈柔和投影，白纸放在白底上也看得出边
   用 drop-shadow 而不是 box-shadow：它会贴着折角的形状走，
   不会在缺掉的那个角上画出方框
   ========================================================= */
.wb-book-modal:not(:has(.wb-ctl-edit.editing)) .wb-entry-content {
  filter:
    drop-shadow(0 0 .5px rgba(0, 0, 0, .35))
    drop-shadow(0 1px 2px rgba(0, 0, 0, .1))
    drop-shadow(0 4px 8px rgba(0, 0, 0, .08)) !important;
}
/* 折角：从白到浅灰的渐变，像纸翻过来的背面 */
.wb-book-modal:not(:has(.wb-ctl-edit.editing)) .wb-entry-content::after {
  background: linear-gradient(225deg, transparent 50%, #fafafa 50%, #dcdce1 100%) !important;
}
/* 展开后的大纸，投影再大一点 */
.wb-book-modal:not(:has(.wb-ctl-edit.editing)) .wb-entry:has(.wb-entry-content:not(.wb-entry-content-collapsed)) .wb-entry-content,
.wb-book-modal:not(:has(.wb-ctl-edit.editing)) .wb-entry:not(:has(.wb-entry-expand-btn)) .wb-entry-content {
  filter:
    drop-shadow(0 0 .5px rgba(0, 0, 0, .3))
    drop-shadow(0 2px 4px rgba(0, 0, 0, .08))
    drop-shadow(0 8px 18px rgba(0, 0, 0, .08)) !important;
}

/* 夜间：黑底上投影看不见，改用一圈淡淡的亮边 + 深色投影 */
@media (prefers-color-scheme: dark) {
  .wb-book-modal:not(:has(.wb-ctl-edit.editing)) .wb-entry-content,
  .wb-book-modal:not(:has(.wb-ctl-edit.editing)) .wb-entry:has(.wb-entry-content:not(.wb-entry-content-collapsed)) .wb-entry-content,
  .wb-book-modal:not(:has(.wb-ctl-edit.editing)) .wb-entry:not(:has(.wb-entry-expand-btn)) .wb-entry-content {
    filter:
      drop-shadow(0 0 .5px rgba(255, 255, 255, .45))
      drop-shadow(0 4px 10px rgba(0, 0, 0, .6)) !important;
  }
  .wb-book-modal:not(:has(.wb-ctl-edit.editing)) .wb-entry-content::after {
    background: linear-gradient(225deg, transparent 50%, #3a3a3c 50%, #545458 100%) !important;
  }
}

value.customCss:
/*⁣​‌‌‍‍​⁠‌‌​​‍⁠⁠‍​‌​​⁠‌‌‍​​‍‍‌​​​‍⁠‌⁠​⁠‌⁠‍‌‍‍‌‌⁠⁠⁠‍‍‍⁠​⁠‌‌‍⁠⁠‌‍‍‌​⁣ ===== 基础卡片 ===== */
.xt-root {
  --xt-accent: #df8f9f;
  font-family: -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
  color: #493d40;
  height: 52vh;
  max-height: 56vh;
  min-height: 260px;
  overflow-y: auto;
  padding: 16px 14px 22px;
  background: linear-gradient(180deg, #fffdfd, #fff6f8);
  border-radius: 20px;
  box-shadow: 0 -8px 30px rgba(89,53,62,.08), 0 12px 35px rgba(89,53,62,.08);
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  scrollbar-width: none;
  position: relative;
}
.xt-root::-webkit-scrollbar { width: 0; height: 0; }

/* ===== 头像 + 名字 ===== */
.xt-header {
  text-align: center;
  padding: 4px 0 14px;
}
.xt-avatar {
  width: 52px; height: 52px;
  border-radius: 50%;
  object-fit: cover;
  border: 3px solid #fff;
  box-shadow: 0 4px 14px rgba(120,73,84,.12);
}
.xt-name {
  margin-top: 6px;
  font-size: 16px;
  font-weight: 650;
  color: #554449;
}

/* ===== Section：便利贴 ===== */
.xt-section {
  position: relative;
  margin: 12px 0;
  padding: 14px 16px;
  /* 便利贴底色：淡粉 */
  background: #ffeef2;
  /* 直边，不圆 */
  border-radius: 0;
  /* 贴上去的轻微阴影 */
  box-shadow: 0 2px 4px rgba(200, 120, 150, 0.10);
  /* 便利贴顶部的胶带条 */
  border-top: 3px solid rgba(223, 143, 159, 0.35);
}

/* 每个 section 顶部加一小条"胶带" */
.xt-section::before {
  content: "";
  position: absolute;
  top: -6px;
  left: 50%;
  transform: translateX(-50%);
  width: 60px;
  height: 12px;
  background: rgba(255, 200, 215, 0.7);
  /* 胶带也是直边 */
  border-radius: 0;
  box-shadow: 0 1px 2px rgba(200, 120, 150, 0.15);
}

.xt-section-title {
  margin-bottom: 8px;
  font-size: 12px;
  font-weight: 650;
  color: #675258;
}

.xt-section-body {
  font-size: 12px;
  line-height: 1.85;
  color: #67575c;
}

/* ===== 引用 ===== */
.xt-quote {
  position: relative;
  padding: 10px 12px 10px 16px;
  background: rgba(255,255,255,.6);
  border-left: 3px solid #df8f9f;
  border-radius: 0;
  color: #66545a;
  font-size: 12px;
  line-height: 1.8;
}

/* ===== 圆环 ===== */
.xt-row {
  display: flex !important;
  flex-direction: row !important;
  gap: 8px;
  align-items: flex-start;
  justify-content: space-around;
}
.xt-row > * {
  flex: 1 !important;
  min-width: 0 !important;
}
.xt-ring {
  width: 100% !important;
  text-align: center;
}
.xt-ring-svg {
  width: 100% !important;
  max-width: 52px !important;
  height: auto !important;
  display: block;
  margin: 0 auto;
}
.xt-ring-track { fill: none; stroke: #ffeef2; stroke-width: 6; }
.xt-ring-fill  { fill: none; stroke: #df8f9f; stroke-width: 6; stroke-linecap: butt; }
.xt-ring-value { font-size: 12px; font-weight: 650; color: #d08091; }
.xt-ring-label { font-size: 9px; color: #a97983; margin-top: 2px; }

/* ===== 进度条 ===== */
.xt-bar {
  margin: 10px 0;
}
.xt-bar-label {
  display: flex;
  justify-content: space-between;
  margin-bottom: 4px;
  font-size: 10px;
  color: #8e797f;
}
.xt-bar-track {
  height: 4px;
  border-radius: 0;
  overflow: hidden;
  background: #ffeef2;
}
.xt-bar-fill {
  height: 100%;
  border-radius: 0;
  background: linear-gradient(90deg, #efbdc8, #df8f9f);
}

/* ===== 标签 ===== */
.xt-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 6px;
}
.xt-tag {
  padding: 5px 10px;
  border-radius: 0;
  background: #ffeef2;
  border: none;
  color: #a97983;
  font-size: 10px;
}

/* ===== 折叠 ===== */
.xt-collapse {
  position: relative;
  margin: 12px 0;
  overflow: hidden;
  border: none;
  border-radius: 0;
  background: #ffeef2;
  box-shadow: 0 2px 4px rgba(200, 120, 150, 0.10);
  border-top: 3px solid rgba(223, 143, 159, 0.35);
}
.xt-collapse::before {
  content: "";
  position: absolute;
  top: -6px;
  left: 50%;
  transform: translateX(-50%);
  width: 60px;
  height: 12px;
  background: rgba(255, 200, 215, 0.7);
  border-radius: 0;
}
.xt-collapse-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  font-size: 11px;
  font-weight: 600;
  color: #705b61;
  cursor: pointer;
}
.xt-collapse-arrow {
  font-size: 14px;
  color: #c57c8b;
  transition: transform .3s;
}
.xt-collapse-body {
  max-height: 0;
  overflow: hidden;
  padding: 0 14px;
  font-size: 11px;
  line-height: 1.8;
  color: #806f74;
  transition: max-height .35s, padding .35s;
}
#xt-t1:checked ~ .xt-content .xt-collapse-1 .xt-collapse-body,
#xt-t2:checked ~ .xt-content .xt-collapse-2 .xt-collapse-body,
#xt-t3:checked ~ .xt-content .xt-collapse-3 .xt-collapse-body {
  max-height: 600px;
  padding: 0 14px 14px;
}
#xt-t1:checked ~ .xt-content .xt-collapse-1 .xt-collapse-arrow,
#xt-t2:checked ~ .xt-content .xt-collapse-2 .xt-collapse-arrow,
#xt-t3:checked ~ .xt-content .xt-collapse-3 .xt-collapse-arrow {
  transform: rotate(90deg);
}

/* ===== 空容器不占位 ===== */
.xt-text:empty,
.xt-bar:empty { display: none; }

/* ===== 底部 ===== */
.xt-footer {
  padding: 14px 0 4px;
  text-align: center;
  color: #b69fa5;
  font-size: 9px;
  letter-spacing: 2px;
}

/* ===== 粒子 ===== */
.xt-particles-hearts .xt-particle {
  opacity: .28;
  color: #e3a0ad;
}

